 12→use crate::ephemeral::{emit_peer_subscribed, emit_peer_unsubscribed};
 13→
 14→// Helper Functions
 15→
 16→/// Extract permit holder's DID from the permit's audience field
 17→///
 18→/// **Context**: The permit holder is the one who can create layers matching their patterns
 19→/// **Note**: The UCAN audience may be stored as base64-encoded public key or DID format.
 20→/// Layer names use DID format (did:key:...), so we normalize to DID for pattern matching.
 21→fn extract_permit_holder_did(permit: &str, fallback_did: &str) -> String {
 22→    match gurkha::Permit::from_token(permit) {
 23→        Ok(parsed) => {
 24→            let raw_aud = parsed.parsed().audience().to_string();
 25→            // If already a DID, use as-is; otherwise convert from base64
 26→            if raw_aud.starts_with("did:key:") {
 27→                raw_aud
 28→            } else {
 29→                // Assume base64-encoded public key, convert to DID
 30→                match herald::Identity::did_from_base64_pubkey(&raw_aud) {
 31→                    Ok(did) => did,
 32→                    Err(e) => {
 33→                        warn!(error = %e, raw_aud = %raw_aud, "Failed to convert audience to DID, using raw value");
 34→                        raw_aud
 35→                    }
 36→                }
 37→            }
 38→        }
 39→        Err(e) => {
 40→            warn!(error = %e, "Failed to extract audience from permit, falling back to provided DID");
 41→            fallback_did.to_string()
 42→        }
 43→    }
 44→}
 45→
 46→// Subscription Handlers
 47→
 48→/// Handle peer subscription
 49→///
 50→/// **Context**: PeerActor subscribes to receive updates for this page
 51→/// **We do**: Parse permit once with gurkha::Permit, store it directly
 52→///
 53→/// **Pattern expansion**: For patterns like `{page_id}/orders/{aud}`, we use the permit's
 54→/// audience field (the permit holder's DID) for expansion, not the subscriber's DID.
 55→/// This ensures layers created by the permit holder match correctly.
 56→#[instrument(skip(state, broadcast_tx, ephemeral_tx, permit_token), fields(page_id = %state.page_id))]
 57→pub async fn handle_subscribe(
 58→    state: &mut ScribeState,
 59→    user_did: String,
 60→    device_id: String,
 61→    broadcast_tx: mpsc::Sender<BroadcastPayload>,
 62→    ephemeral_tx: Option<mpsc::Sender<EphemeralOutbound>>,
 63→    permit_token: String,
 64→) {
 65→    info!(user_did = %user_did, device_id = %device_id, permit_len = permit_token.len(), "Peer subscribing");
 66→
 67→    // Parse permit once - store directly, no extraction needed
 68→    let permit = match gurkha::Permit::from_token(&permit_token) {
 69→        Ok(p) => p,
 70→        Err(e) => {
 71→            warn!(error = ?e, "Failed to parse permit, rejecting subscription");
 72→            return;
 73→        }
 74→    };
 75→
 76→    // Extract permit holder's DID for pattern expansion
 77→    // The UCAN audience may be base64-encoded public key or DID format
 78→    let permit_holder_did = extract_permit_holder_did(&permit_token, &user_did);
 79→
 80→    // Load stored state vectors for this peer, normalizing keys to bare names
 81→    let vectors = match state.vector_storage.load_vectors(&user_did, &device_id) {
 82→        Ok(Some(v)) => v.into_iter()
 83→            .map(|(k, v)| (normalize_layer_name(&k, &state.page_id), v))
 84→            .collect(),
 85→        Ok(None) => HashMap::new(),
 86→        Err(e) => {
 87→            warn!(error = %e, "Failed to load peer vectors");
 88→            HashMap::new()
 89→        }
 90→    };
 91→
 92→    // Extract presence info from permit
 93→    let is_visible = permit.is_visible();
 94→    let can_see_others = permit.can_see_others();
 95→    let display_name = permit.display_name().map(String::from);
 96→
 97→    info!(
 98→        user_did = %user_did,
 99→        permit_holder_did = %permit_holder_did,
100→        is_visible = is_visible,
101→        display_name = ?display_name,
102→        layers = ?permit.layers().keys().collect::<Vec<_>>(),
103→        patterns = ?permit.layer_patterns().keys().collect::<Vec<_>>(),
104→        "Subscription with permit stored directly"
105→    );
106→
107→    if let Ok(mut subs) = state.subscribers.write() {
108→        subs.insert(
109→            (user_did.clone(), device_id.clone()),
110→            SubscriberInfo {
111→                permit: permit.clone(),
112→                subscriber_did: permit_holder_did.clone(),
113→                is_visible,
114→                can_see_others,
115→                display_name: display_name.clone(),
116→                broadcast_tx: broadcast_tx.clone(),
117→                ephemeral_tx,
118→                vectors,
119→            },
120→        );
121→        debug!(subscriber_count = subs.len(), "Subscriber added");
122→    }
123→
124→    // Populate authorized_dids on existing LayerUnits for this subscriber
125→    authorize_subscriber_for_layers(state, &user_did, &permit, &permit_holder_did, can_see_others);
126→
127→    // Notify app subscribers about peer joining (lifecycle event)
128→    emit_peer_subscribed(state, &user_did);
129→
130→    // Send initial state to new subscriber for layers they have access to
131→    send_initial_state_to_subscriber(
132→        state,
133→        &user_did,
134→        &device_id,
135→        &broadcast_tx,
136→    ).await;
137→
138→    // Issue pending layer permits for explicit dynamic layers (node mode only)
139→    issue_pending_layer_permits(state, &user_did, &device_id).await;
140→
141→    // Emit subscriber state snapshot for observability
142→    let authorized_layers: Vec<String> = state.units.iter()
143→        .filter(|(_, unit)| unit.is_authorized(&user_did))
144→        .map(|(name, _)| name.clone())
145→        .collect();
146→    state.emit_subscriber_state_capture(
147→        &user_did,
148→        &authorized_layers,
149→        state.units.len(),
150→        can_see_others,
151→        is_visible,
152→    );
153→}
154→
155→/// Populate authorized_dids on all existing LayerUnits for a newly subscribed peer
156→///
157→/// **Context**: Peer just subscribed with a page permit. Check each layer
158→/// against their permit and authorize accordingly.
159→fn authorize_subscriber_for_layers(
160→    state: &ScribeState,
161→    user_did: &str,
162→    permit: &gurkha::Permit,
163→    permit_holder_did: &str,
164→    can_see_others: bool,
165→) {
166→    let sync_target = state
167→        .sync_config
168→        .as_ref()
169→        .and_then(|cfg| cfg.sync_target.as_deref());
170→
171→    for (layer_name, unit) in &state.units {
172→        if unit.is_local_only() { continue; }
173→
174→        if layer_name.starts_with("__sync_meta/") {
175→            let did_in_layer = layer_name.trim_start_matches("__sync_meta/");
176→            if user_did == did_in_layer || sync_target == Some(user_did) {
177→                unit.authorize_did(user_did);
178→                state.emit_layer_auth_capture(layer_name, user_did, "authorized_protocol_sync_meta");
179→            }
180→            continue;
181→        }
182→
183→        // Presence layer: only if can_see_others
184→        if (layer_name == "presence" || layer_name.ends_with("/presence")) && !can_see_others {
185→            continue;
186→        }
187→
188→        // no_incoming_updates check
189→        if permit.sync_facts().no_incoming_updates.contains(&layer_name.to_string()) {
190→            continue;
191→        }
192→
193→        // Check if page permit covers this layer
194→        if permit.can_read_layer(layer_name, &state.page_id, permit_holder_did) {
195→            unit.authorize_did(user_did);
196→            state.emit_layer_auth_capture(layer_name, user_did, "authorized_page_permit");
197→        }
198→    }
199→}
200→
201→/// Handle peer unsubscription
202→#[instrument(skip(state), fields(page_id = %state.page_id))]
203→pub async fn handle_unsubscribe(
204→    state: &mut ScribeState,
205→    user_did: &str,
206→    device_id: &str,
207→) {
208→    info!(user_did = %user_did, device_id = %device_id, "Peer unsubscribing");
209→
210→    if let Ok(mut subs) = state.subscribers.write() {
211→        // Save their vectors before removing
212→        if let Some(info) = subs.get(&(user_did.to_string(), device_id.to_string())) {
213→            if let Err(e) = state.vector_storage.save_vectors(user_did, device_id, &info.vectors) {
214→                warn!(error = %e, "Failed to save peer vectors on unsubscribe");
215→            }
216→        }
217→
218→        subs.remove(&(user_did.to_string(), device_id.to_string()));
219→        debug!(subscriber_count = subs.len(), "Subscriber removed");
220→    }
221→
222→    // Remove DID from all LayerUnits' authorized_dids
223→    for (_, unit) in &state.units {
224→        unit.revoke_did(user_did);
225→    }
226→
227→    // Notify app subscribers about peer leaving (lifecycle event)
228→    emit_peer_unsubscribed(state, user_did);
229→}
230→
231→// Initial State Delivery
232→
233→/// Send initial state to a newly subscribed peer
234→///
235→/// **Context**: Peer just subscribed, may have missed previous updates
236→/// **We do**: Send current snapshot for each layer they have permission for
237→/// **Checks**: Uses LayerUnit.is_authorized() (populated by authorize_subscriber_for_layers)
238→#[instrument(skip_all, fields(page_id = %state.page_id, user_did = %user_did))]
239→async fn send_initial_state_to_subscriber(
240→    state: &ScribeState,
241→    user_did: &str,
242→    device_id: &str,
243→    broadcast_tx: &mpsc::Sender<BroadcastPayload>,
244→) {
245→    // Get peer's stored vectors (if any), normalizing keys to bare names
246→    let peer_vectors = match state.vector_storage.load_vectors(user_did, device_id) {
247→        Ok(Some(v)) => v.into_iter()
248→            .map(|(k, v)| (normalize_layer_name(&k, &state.page_id), v))
249→            .collect(),
250→        Ok(None) => HashMap::new(),
251→        Err(_) => HashMap::new(),
252→    };
253→
254→    for (layer_name, unit) in &state.units {
255→        let layer = unit.layer();
256→
257→        // Check if they're authorized for this layer (populated at subscribe time)
258→        if !unit.is_authorized(user_did) {
259→            continue;
260→        }
261→
262→        // Determine what to send: incremental or full snapshot
263→        let data = if let Some(their_vector) = peer_vectors.get(layer_name) {
264→            if their_vector.is_empty() {
265→                layer.export_snapshot()
266→            } else {
267→                match layer.export_updates(their_vector) {
268→                    Ok(updates) if updates.is_empty() => {
269→                        // No new updates since their last sync
270→                        debug!(user_did = %user_did, layer = %layer_name, "No new updates for subscriber");
271→                        continue;
272→                    }
273→                    Ok(updates) => updates,
274→                    Err(e) => {
275→                        warn!(error = %e, layer = %layer_name, "Failed to export incremental, using snapshot");
276→                        layer.export_snapshot()
277→                    }
278→                }
279→            }
280→        } else {
281→            // No stored vector - send full snapshot
282→            layer.export_snapshot()
283→        };
284→
285→        // Get our current state vector for 3-step sync protocol
286→        let state_vector = layer.version_vector();
287→
288→        // Skip empty data or empty state vectors (no operations).
289→        // Protocol sync metadata must still be sent as initial snapshot so the
290→        // remote side materializes the layer for pairwise sync state.
291→        let is_protocol_sync_meta = layer_name.starts_with("__sync_meta/");
292→        if data.is_empty() || (!is_protocol_sync_meta && state_vector.len() <= 1) {
293→            debug!(user_did = %user_did, layer = %layer_name, "Skipping empty layer in initial state");
294→            continue;
295→        }
296→
297→        let payload = BroadcastPayload {
298→            page_id: state.page_id.clone(),
299→            layer_name: layer_name.clone(),
300→            layer_type: domains::LayerType::from_layer_name(layer_name),
301→            update: data,
302→            state_vector,
303→        };
304→
305→        if let Err(e) = broadcast_tx.try_send(payload) {
306→            warn!(user_did = %user_did, layer = %layer_name, error = %e, "Failed to send initial state");
307→        } else {
308→            debug!(user_did = %user_did, layer = %layer_name, "Sent initial state to subscriber");
309→        }
310→    }
311→}
312→
313→/// Issue pending layer permits for a newly subscribed peer (node mode only)
314→///
315→/// **Context**: Peer just subscribed. Compute missing access permits from
316→/// authority permits and issue fresh layer permits.
317→#[instrument(skip_all, fields(page_id = %state.page_id, user_did = %user_did))]
318→async fn issue_pending_layer_permits(
319→    state: &ScribeState,
320→    user_did: &str,
321→    _device_id: &str,
322→) {
323→    let Some(ref issuer) = state.permit_issuer else { return; };
324→    let Some(ref sync_event_tx) = state.sync_event_tx else { return; };
325→
326→    let authority_permits = match issuer.list_layer_authority_permits_for_audience(user_did) {
327→        Ok(permits) => permits,
328→        Err(e) => {
329→            warn!(error = %e, "Failed to list layer authority permits for subscriber");
330→            return;
331→        }
332→    };
333→
334→    for (layer_name, _version, authority_token) in authority_permits {
335→        let already_issued = match issuer.has_layer_access_permit(user_did, &layer_name) {
336→            Ok(v) => v,
337→            Err(e) => {
338→                warn!(error = %e, layer = %layer_name, "Failed to check existing layer permit");
339→                continue;
340→            }
341→        };
342→        if already_issued {
343→            continue;
344→        }
345→
346→        let Some(config) = authority_layer_config(&authority_token, &layer_name, &state.page_id) else {
347→            warn!(layer = %layer_name, "Authority permit missing layer config for subscriber");
348→            continue;
349→        };
350→
351→        let intent_cid = match gurkha::crypto::get_permit_cid(&authority_token) {
352→            Ok(cid) => cid,
353→            Err(e) => {
354→                warn!(error = %e, layer = %layer_name, "Failed to compute authority permit CID");
355→                continue;
356→            }
357→        };
358→
359→        match issuer.issue_layer_permit(user_did, &layer_name, config, Some(&intent_cid)) {
360→            Ok((token, _cid)) => {
361→                let bare_name = normalize_layer_name(&layer_name, &state.page_id);
362→                if let Some(unit) = state.units.get(&bare_name) {
363→                    unit.authorize_did(user_did);
364→                    state.emit_layer_auth_capture(&bare_name, user_did, "authorized_layer_permit");
365→                }
366→
367→                let event = SyncEvent::LayerAccessChanged {
368→                    page_id: state.page_id.clone(),
369→                    layer_name: layer_name.to_string(),
370→                    permits: vec![(user_did.to_string(), token)],
371→                };
372→                state.emit_sync_event_capture(&event);
373→                if let Err(e) = sync_event_tx.send(event).await {
374→                    warn!(error = %e, layer = %layer_name, "Failed to emit pending layer permit");
375→                }
376→            }
377→            Err(e) => warn!(error = %e, layer = %layer_name, "Failed to issue pending layer permit"),
378→        }
379→    }
380→}
381→
382→fn authority_layer_config(
383→    authority_token: &str,
384→    layer_name: &str,
385→    page_id: &str,
386→) -> Option<gurkha::LayerConfig> {
387→    let parsed = gurkha::Permit::from_token(authority_token).ok()?;
388→
389→    if let Some(config) = parsed.layers().get(layer_name) {
390→        return Some(config.clone());
391→    }
392→
393→    let bare = normalize_layer_name(layer_name, page_id);
394→    if let Some(config) = parsed.layers().get(&bare) {
395→        return Some(config.clone());
396→    }
397→
398→    None
399→}
