  1→//! 3-Step Sync Protocol
  2→//!
  3→//! Handles the SyncOffer → SyncAccept → SyncAck protocol for CRDT synchronization.
  4→//! Also includes asset sync triggering after layer sync completes.
  5→//!
  6→//! ## Bounded Resync Protocol
  7→//!
  8→//! When vectors diverge after SyncOffer/SyncAccept, we resync. But to prevent
  9→//! infinite loops, we track resync attempts:
 10→//!
 11→//! 1. `resync_attempts < MAX_RESYNC_ATTEMPTS`: Send another SyncOffer
 12→//! 2. `resync_attempts >= MAX_RESYNC_ATTEMPTS`: Send SyncReset (request full snapshot)
 13→//! 3. Node responds with SyncSnapshot (authoritative full state)
 14→//! 4. User replaces local layer entirely
 15→//!
 16→//! **Invariant**: Node is source of truth for divergence resolution.
 17→
 18→use tracing::{debug, error, info, trace, warn, instrument};
 19→use std::collections::BTreeSet;
 20→
 21→use crate::message::*;
 22→use transport::Connection;
 23→
 24→use super::super::guards::require_auth;
 25→use super::super::{PeerActor, PeerActorState, MAX_RESYNC_ATTEMPTS};
 26→
 27→impl<C: Connection> PeerActor<C> {
 28→
 29→    fn is_sync_meta_layer(page_id: &str, layer_name: &str) -> bool {
 30→        layer_name.starts_with("__sync_meta/")
 31→            || layer_name.starts_with(&format!("{}/__sync_meta/", page_id))
 32→    }
 33→
 34→    fn authority_schema_for_layer<'a>(
 35→        permit: &'a gurkha::Permit,
 36→        page_id: &str,
 37→        layer_name: &str,
 38→    ) -> Option<&'a gurkha::DynamicLayerSchema> {
 39→        let schemas = permit.dynamic_layer_schemas();
 40→        if schemas.is_empty() {
 41→            return None;
 42→        }
 43→
 44→        let bare_path = layer_name
 45→            .strip_prefix(&format!("{}/", page_id))
 46→            .unwrap_or(layer_name);
 47→        let path_parts: Vec<&str> = bare_path.split('/').collect();
 48→        if path_parts.len() < 3 || !path_parts[1].starts_with("did:") {
 49→            return None;
 50→        }
 51→
 52→        for (schema_key, schema) in schemas {
 53→            let pattern_parts: Vec<&str> = schema_key.split('/').collect();
 54→            if path_parts.len() != pattern_parts.len() + 1 {
 55→                continue;
 56→            }
 57→            if path_parts[0] != pattern_parts[0] {
 58→                continue;
 59→            }
 60→
 61→            let mut matched = true;
 62→            for (path_seg, pat_seg) in path_parts[2..].iter().zip(pattern_parts[1..].iter()) {
 63→                if *pat_seg != "{id}" && path_seg != pat_seg {
 64→                    matched = false;
 65→                    break;
 66→                }
 67→            }
 68→
 69→            if matched {
 70→                return Some(schema);
 71→            }
 72→        }
 73→
 74→        None
 75→    }
 76→
 77→    async fn fanout_sync_meta_from_authority(
 78→        &self,
 79→        page_id: &str,
 80→        layer_name: &str,
 81→        authority_permit: &gurkha::Permit,
 82→        scribe: &ractor::ActorRef<butler::ScribeMessage>,
 83→        state: &PeerActorState<C>,
 84→    ) {
 85→        let our_did = match state.butler.user_info().await {
 86→            Ok(info) => info.did,
 87→            Err(e) => {
 88→                warn!(error = %e, "Unable to resolve node DID for sync-meta fanout");
 89→                return;
 90→            }
 91→        };
 92→
 93→        let mut recipients = BTreeSet::new();
 94→        match authority_permit.authorized_peers() {
 95→            Ok(Some(explicit)) => {
 96→                for did in explicit {
 97→                    if did != our_did {
 98→                        recipients.insert(did);
 99→                    }
100→                }
101→            }
102→            Ok(None) => {
103→                let Some(schema) = Self::authority_schema_for_layer(authority_permit, page_id, layer_name) else {
104→                    warn!(page_id = %page_id, layer = %layer_name, "No matching dynamic schema in authority permit for role fanout");
105→                    return;
106→                };
107→
108→                let all_users = match state.butler.store().list_authorized_users_for_page(page_id) {
109→                    Ok(users) => users,
110→                    Err(e) => {
111→                        warn!(error = %e, "Failed to list authorized users for role fanout");
112→                        return;
113→                    }
114→                };
115→
116→                for user_did in all_users {
117→                    if user_did == our_did {
118→                        continue;
119→                    }
120→
121→                    let permit_token = match state.butler.store().get_user_page_permit(page_id, &user_did) {
122→                        Ok(Some(p)) => p,
123→                        _ => continue,
124→                    };
125→
126→                    let parsed = match gurkha::Permit::from_token(&permit_token) {
127→                        Ok(p) => p,
128→                        Err(_) => continue,
129→                    };
130→
131→                    let role = parsed
132→                        .get_fact("role")
133→                        .and_then(|v| v.as_str())
134→                        .or_else(|| parsed.get_fact("relationship").and_then(|v| v.as_str()));
135→
136→                    if let Some(role) = role {
137→                        if schema.role_permissions.contains_key(role) {
138→                            recipients.insert(user_did);
139→                        }
140→                    }
141→                }
142→            }
143→            Err(e) => {
144→                warn!(error = %e, "Invalid authorized_peers in layer authority permit");
145→                return;
146→            }
147→        }
148→
149→        for did in recipients {
150→            let sync_meta_layer = format!("__sync_meta/{}", did);
151→            let sync_meta_key = layer_name
152→                .strip_prefix(&format!("{}/", page_id))
153→                .unwrap_or(layer_name)
154→                .to_string();
155→            if let Err(e) = scribe.cast(butler::ScribeMessage::MapInsert {
156→                layer_name: sync_meta_layer,
157→                path: String::new(),
158→                key: sync_meta_key,
159→                value: serde_json::json!({"synced": false, "version": 1}),
160→            }) {
161→                warn!(page_id = %page_id, layer = %layer_name, target = %did, error = %e, "Failed to write recipient sync-meta entry");
162→            }
163→        }
164→    }
165→
166→    #[instrument(skip(self, state, scribe), fields(page_id = %page_id, sync_meta_layer = %sync_meta_layer))]
167→    async fn request_missing_layers_from_sync_meta(
168→        &self,
169→        page_id: &str,
170→        sync_meta_layer: &str,
171→        scribe: &ractor::ActorRef<butler::ScribeMessage>,
172→        state: &mut PeerActorState<C>,
173→    ) {
174→        let normalized_sync_meta_layer = sync_meta_layer
175→            .strip_prefix(&format!("{}/", page_id))
176→            .unwrap_or(sync_meta_layer)
177→            .to_string();
178→
179→        let (data_tx, data_rx) = tokio::sync::oneshot::channel();
180→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetLayerData {
181→            layer_name: normalized_sync_meta_layer,
182→            reply: data_tx,
183→        }) {
184→            warn!(error = %e, "Failed to read sync-meta layer for request planning");
185→            return;
186→        }
187→
188→        let sync_meta_json = match data_rx.await {
189→            Ok(Ok(v)) => v,
190→            Ok(Err(e)) => {
191→                warn!(error = %e, "GetLayerData failed for sync-meta layer");
192→                return;
193→            }
194→            Err(_) => {
195→                warn!("GetLayerData reply channel closed for sync-meta layer");
196→                return;
197→            }
198→        };
199→
200→        let Some(entries) = sync_meta_json.as_object() else {
201→            warn!("sync-meta layer content is not a map object");
202→            return;
203→        };
204→
205→        for (layer_name, entry) in entries {
206→            let normalized_layer_name = layer_name
207→                .strip_prefix(&format!("{}/", page_id))
208→                .unwrap_or(layer_name)
209→                .to_string();
210→
211→            if normalized_layer_name.starts_with("__sync_meta/") {
212→                continue;
213→            }
214→
215→            let should_request = entry
216→                .get("synced")
217→                .and_then(serde_json::Value::as_bool)
218→                .map(|s| !s)
219→                .unwrap_or(true);
220→            if !should_request {
221→                continue;
222→            }
223→
224→            let (exists_tx, exists_rx) = tokio::sync::oneshot::channel();
225→            if let Err(e) = scribe.cast(butler::ScribeMessage::LayerExists {
226→                layer_name: normalized_layer_name.clone(),
227→                reply: exists_tx,
228→            }) {
229→                warn!(layer = %normalized_layer_name, error = %e, "Failed to check layer existence");
230→                continue;
231→            }
232→
233→            let exists = match exists_rx.await {
234→                Ok(v) => v,
235→                Err(_) => {
236→                    warn!(layer = %normalized_layer_name, "LayerExists reply channel closed");
237→                    continue;
238→                }
239→            };
240→
241→            if exists {
242→                continue;
243→            }
244→
245→            info!(page_id = %page_id, layer = %normalized_layer_name, "Requesting missing layer via SyncReset after sync-meta discovery");
246→            let msg = Message::SyncReset(SyncResetMsg {
247→                page_id: page_id.to_string(),
248→                layer_name: normalized_layer_name,
249→            });
250→            self.send_message(&msg, state).await;
251→        }
252→    }
253→
254→    /// Handle incoming SyncOffer from peer (Step 1)
255→    ///
256→    /// **Context**: Peer has a layer update with their state vector
257→    /// **Peer sends**: SyncOffer with page_id, layer_name, encrypted data, state_vector
258→    /// **We decrypt**: ECDH with ephemeral_public + our encryption key
259→    /// **We apply**: Via Scribe.ApplyUpdateWithResult (handles merge)
260→    /// **We respond**: SyncAccept with our state vector after applying (only if successful)
261→    #[instrument(skip(self, myself, state, data, their_state_vector, ephemeral_public), fields(page_id = %page_id, layer_name = %layer_name))]
262→    pub(in crate::peer_actor) async fn on_sync_offer(
263→        &self,
264→        myself: ractor::ActorRef<super::super::PeerMessage>,
265→        page_id: &str,
266→        layer_name: &str,
267→        data: &[u8],
268→        their_state_vector: &[u8],
269→        ephemeral_public: &[u8; 32],
270→        authority_permit: Option<&str>,
271→        state: &mut PeerActorState<C>,
272→    ) {
273→        let (peer_did, _) = match require_auth(&state.state) {
274→            Ok(info) => (info.0.to_string(), info.1.to_string()),
275→            Err(_) => {
276→                warn!("SyncOffer from unauthenticated peer: {}", self.node_id);
277→                return;
278→            }
279→        };
280→
281→        let peer_device_id = self.node_id.to_string();
282→
283→        debug!(
284→            "SyncOffer: page={} layer={} ({} bytes, vector {} bytes) from {}",
285→            page_id, layer_name, data.len(), their_state_vector.len(), peer_did
286→        );
287→
288→        // Open page early so bundled authority fanout and apply share one Scribe handle.
289→        let scribe = match state.butler.open_page(page_id).await {
290→            Ok(s) => s,
291→            Err(e) => {
292→                error!("Failed to open page {}: {}", page_id, e);
293→                return;
294→            }
295→        };
296→
297→        if let Some(permit) = authority_permit {
298→            match gurkha::Permit::from_token(permit) {
299→                Ok(parsed) => {
300→                    if parsed.token_type() == Some("layer_authority") {
301→                        let audience = parsed.parsed().audience().to_string();
302→                        let version = parsed
303→                            .get_fact("version")
304→                            .and_then(|v| v.as_u64())
305→                            .unwrap_or(0);
306→                        let full_layer_name = if layer_name.starts_with(&format!("{}/", page_id)) {
307→                            layer_name.to_string()
308→                        } else {
309→                            format!("{}/{}", page_id, layer_name)
310→                        };
311→                        if let Err(e) = state.butler.permits().store_layer_authority_permit(
312→                            page_id,
313→                            &full_layer_name,
314→                            &audience,
315→                            version,
316→                            permit,
317→                        ) {
318→                            warn!(
319→                                page_id = %page_id,
320→                                layer = %full_layer_name,
321→                                audience = %audience,
322→                                error = %e,
323→                                "Failed to store bundled layer authority permit"
324→                            );
325→                        }
326→
327→                        if state.mode == crate::CourierMode::Node {
328→                            self
329→                                .fanout_sync_meta_from_authority(
330→                                    page_id,
331→                                    &full_layer_name,
332→                                    &parsed,
333→                                    &scribe,
334→                                    state,
335→                                )
336→                                .await;
337→                        }
338→                    }
339→                }
340→                Err(e) => {
341→                    warn!(page_id = %page_id, layer = %layer_name, error = %e, "Invalid bundled authority permit in SyncOffer");
342→                }
343→            }
344→        }
345→
346→        // Decrypt transit-encrypted update using ECDH
347→        let our_secret = match state.butler.encryption_key().await {
348→            Ok(key) => key,
349→            Err(e) => {
350→                error!("Failed to get encryption key for SyncOffer decryption: {}", e);
351→                return;
352→            }
353→        };
354→        let decrypted_data = match herald::decrypt_from_transfer(&our_secret, ephemeral_public, data) {
355→            Ok(data) => data,
356→            Err(e) => {
357→                error!("Failed to decrypt SyncOffer from {}: {}", peer_did, e);
358→                return;
359→            }
360→        };
361→
362→        // Auto-subscribe peer if not already subscribed (both Node and User modes)
363→        // For Node mode: Ensures can_write() can check viewer's write permissions
364→        // For User mode: Ensures node gets subscribed to viewer's scribe for bidirectional sync
365→        if !state.page_subscriptions.contains_key(page_id) {
366→            info!("Auto-subscribing peer {} to page {} from SyncOffer", peer_did, page_id);
367→            self.subscribe_to_page(myself.clone(), page_id, "", state).await;
368→        }
369→
370→        // Apply the update with result feedback
371→        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
372→        if let Err(e) = scribe.cast(butler::ScribeMessage::ApplyUpdateWithResult {
373→            layer_name: layer_name.to_string(),
374→            update: decrypted_data,
375→            from_peer: Some((peer_did.clone(), peer_device_id.clone())),
376→            permit: None,
377→            reply: reply_tx,
378→        }) {
379→            error!("Failed to send ApplyUpdateWithResult to Scribe: {}", e);
380→            return;
381→        }
382→
383→        // Wait for apply result - only send SyncAccept if successful
384→        match reply_rx.await {
385→            Ok(Ok(())) => {
386→                debug!("ApplyUpdate succeeded for page={} layer={}", page_id, layer_name);
387→
388→                if Self::is_sync_meta_layer(page_id, layer_name) {
389→                    self
390→                        .request_missing_layers_from_sync_meta(page_id, layer_name, &scribe, state)
391→                        .await;
392→                }
393→            }
394→            Ok(Err(e)) => {
395→                warn!("ApplyUpdate rejected for page={} layer={}: {}", page_id, layer_name, e);
396→                // DO NOT send SyncAccept - this stops the infinite retry loop
397→                return;
398→            }
399→            Err(_) => {
400→                error!("ApplyUpdate reply channel closed for page={} layer={}", page_id, layer_name);
401→                return;
402→            }
403→        }
404→
405→        // Get our state vector after applying
406→        let (tx, rx) = tokio::sync::oneshot::channel();
407→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetStateVector {
408→            layer_name: layer_name.to_string(),
409→            reply: tx.into(),
410→        }) {
411→            error!("Failed to request state vector from Scribe: {}", e);
412→            return;
413→        }
414→
415→        let our_state_vector = match rx.await {
416→            Ok(Ok(vector)) => vector,
417→            Ok(Err(e)) => {
418→                error!("Scribe returned error getting state vector: {}", e);
419→                return;
420→            }
421→            Err(_) => {
422→                error!("Scribe dropped state vector reply channel");
423→                return;
424→            }
425→        };
426→
427→        // Send SyncAccept with our state vector
428→        let msg = Message::SyncAccept(SyncAcceptMsg {
429→            page_id: page_id.to_string(),
430→            layer_name: layer_name.to_string(),
431→            state_vector: our_state_vector.clone(),
432→        });
433→
434→        self.send_message(&msg, state).await;
435→        debug!(
436→            "Sent SyncAccept for page={} layer={} to {} (our vector {} bytes)",
437→            page_id, layer_name, peer_did, our_state_vector.len()
438→        );
439→    }
440→
441→    /// Handle incoming SyncAccept from peer (Step 2)
442→    ///
443→    /// **Context**: Peer applied our update and reports their state vector
444→    /// **Peer sends**: SyncAccept with their state vector after applying
445→    /// **We compare**: Their vector with our current vector
446→    /// **If match**: Send SyncAck (sync complete)
447→    /// **If diverged**: Send new SyncOffer with full diff from their vector (resync)
448→    #[instrument(skip(self, state, their_state_vector), fields(page_id = %page_id, layer_name = %layer_name))]
449→    pub(in crate::peer_actor) async fn on_sync_accept(
450→        &self,
451→        page_id: &str,
452→        layer_name: &str,
453→        their_state_vector: &[u8],
454→        state: &mut PeerActorState<C>,
455→    ) {
456→        let (peer_did, _) = match require_auth(&state.state) {
457→            Ok(info) => (info.0.to_string(), info.1.to_string()),
458→            Err(_) => {
459→                warn!("SyncAccept from unauthenticated peer: {}", self.node_id);
460→                return;
461→            }
462→        };
463→
464→        debug!(
465→            "SyncAccept: page={} layer={} from {} (their vector {} bytes)",
466→            page_id, layer_name, peer_did, their_state_vector.len()
467→        );
468→
469→        // Get pending sync context (may not exist for fire-and-forget broadcasts)
470→        let key = (page_id.to_string(), layer_name.to_string());
471→        let pending = state.pending_sync_offers.remove(&key);
472→
473→        // Get our current state vector from Scribe
474→        let scribe = match state.butler.open_page(page_id).await {
475→            Ok(s) => s,
476→            Err(e) => {
477→                error!("Failed to open page {}: {}", page_id, e);
478→                return;
479→            }
480→        };
481→
482→        let (tx, rx) = tokio::sync::oneshot::channel();
483→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetStateVector {
484→            layer_name: layer_name.to_string(),
485→            reply: tx.into(),
486→        }) {
487→            error!("Failed to request state vector from Scribe: {}", e);
488→            return;
489→        }
490→
491→        let our_current_vector = match rx.await {
492→            Ok(Ok(vector)) => vector,
493→            Ok(Err(e)) => {
494→                error!("Scribe returned error getting state vector: {}", e);
495→                return;
496→            }
497→            Err(_) => {
498→                error!("Scribe dropped state vector reply channel");
499→                return;
500→            }
501→        };
502→
503→        // Handle based on whether we have a pending offer
504→        match pending {
505→            None => {
506→                // Fire-and-forget broadcast: No pending offer tracked.
507→                // Just update peer vector cache and send SyncAck. Trust CRDT to converge.
508→                debug!(
509→                    "SyncAccept: no pending offer (fire-and-forget) for page={} layer={} - sending SyncAck",
510→                    page_id, layer_name
511→                );
512→
513→                let msg = Message::SyncAck(SyncAckMsg {
514→                    page_id: page_id.to_string(),
515→                    layer_name: layer_name.to_string(),
516→                    state_vector: our_current_vector,
517→                });
518→                self.send_message(&msg, state).await;
519→
520→                // Update Scribe's in-memory vector cache (persistence via periodic flush)
521→                let peer_device_id = self.node_id.to_string();
522→                if let Some(subscription) = state.page_subscriptions.get(page_id) {
523→                    let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
524→                        user_did: peer_did,
525→                        device_id: peer_device_id,
526→                        layer_name: layer_name.to_string(),
527→                        state_vector: their_state_vector.to_vec(),
528→                    });
529→                }
530→            }
531→            Some(offer) => {
532→                // Tracked sync (initial sync / reconciliation): Compare vectors
533→                trace!(
534→                    "SyncAccept comparison: their_vector={} bytes, offered_vector={} bytes, current_vector={} bytes",
535→                    their_state_vector.len(),
536→                    offer.our_state_vector.len(),
537→                    our_current_vector.len()
538→                );
539→
540→                if their_state_vector == offer.our_state_vector.as_slice() {
541→                    // In sync! Send SyncAck
542→                    trace!(
543→                        "SyncAccept: vectors match for page={} layer={} - sending SyncAck",
544→                        page_id, layer_name
545→                    );
546→
547→                    let msg = Message::SyncAck(SyncAckMsg {
548→                        page_id: page_id.to_string(),
549→                        layer_name: layer_name.to_string(),
550→                        state_vector: our_current_vector,
551→                    });
552→                    self.send_message(&msg, state).await;
553→
554→                    // Update Scribe's in-memory vector cache (persistence via periodic flush)
555→                    let peer_device_id = self.node_id.to_string();
556→                    if let Some(subscription) = state.page_subscriptions.get(page_id) {
557→                        let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
558→                            user_did: peer_did,
559→                            device_id: peer_device_id,
560→                            layer_name: layer_name.to_string(),
561→                            state_vector: their_state_vector.to_vec(),
562→                        });
563→                    }
564→                } else {
565→                    // Diverged! Check if we should resync or fall back to SyncReset
566→                    let new_attempts = offer.resync_attempts + 1;
567→
568→                    if new_attempts > MAX_RESYNC_ATTEMPTS {
569→                        // Max resyncs exceeded - fall back to SyncReset (request full snapshot)
570→                        warn!(
571→                            "SyncAccept: max resyncs ({}) exceeded for page={} layer={} - sending SyncReset",
572→                            MAX_RESYNC_ATTEMPTS, page_id, layer_name
573→                        );
574→
575→                        let msg = Message::SyncReset(SyncResetMsg {
576→                            page_id: page_id.to_string(),
577→                            layer_name: layer_name.to_string(),
578→                        });
579→                        self.send_message(&msg, state).await;
580→                        return;
581→                    }
582→
583→                    // Still have retries - send resync SyncOffer with full diff from their vector
584→                    info!(
585→                        "SyncAccept: vectors DIVERGED for page={} layer={} - sending resync SyncOffer (attempt {}/{})",
586→                        page_id, layer_name, new_attempts, MAX_RESYNC_ATTEMPTS
587→                    );
588→
589→                    // Get diff from their state vector
590→                    let (tx, rx) = tokio::sync::oneshot::channel();
591→                    if let Err(e) = scribe.cast(butler::ScribeMessage::GetUpdatesSince {
592→                        layer_name: layer_name.to_string(),
593→                        state_vector: their_state_vector.to_vec(),
594→                        reply: tx,
595→                    }) {
596→                        error!("Failed to request updates from Scribe: {}", e);
597→                        return;
598→                    }
599→
600→                    let diff = match rx.await {
601→                        Ok(Ok(d)) => d,
602→                        Ok(Err(e)) => {
603→                            error!("Scribe returned error getting updates: {}", e);
604→                            return;
605→                        }
606→                        Err(_) => {
607→                            error!("Scribe dropped updates reply channel");
608→                            return;
609→                        }
610→                    };
611→
612→                    // Encrypt and send new SyncOffer
613→                    let peer_encryption_key = match state.peer_encryption_key {
614→                        Some(key) => key,
615→                        None => {
616→                            warn!("Cannot send resync SyncOffer: peer encryption key not set");
617→                            return;
618→                        }
619→                    };
620→
621→                    let (ephemeral_public, encrypted_data) = match herald::encrypt_for_transfer(
622→                        &peer_encryption_key,
623→                        &diff,
624→                    ) {
625→                        Ok(result) => result,
626→                        Err(e) => {
627→                            error!("Failed to encrypt resync data: {}", e);
628→                            return;
629→                        }
630→                    };
631→
632→                    // Track this new pending sync with incremented attempt counter
633→                    state.pending_sync_offers.insert(
634→                        key,
635→                        super::super::PendingSyncOffer {
636→                            our_state_vector: our_current_vector.clone(),
637→                            permit: String::new(),
638→                            resync_attempts: new_attempts,
639→                        },
640→                    );
641→
642→                    let layer_name_owned = layer_name.to_string();
643→                    let msg = Message::SyncOffer(SyncOfferMsg {
644→                        page_id: page_id.to_string(),
645→                        layer_type: LayerType::from_layer_name(&layer_name_owned),
646→                        layer_name: layer_name_owned,
647→                        data: encrypted_data,
648→                        state_vector: our_current_vector,
649→                        ephemeral_public,
650→                        authority_permit: None,
651→                    });
652→                    self.send_message(&msg, state).await;
653→                }
654→            }
655→        }
656→    }
657→
658→    /// Handle incoming SyncAck from peer (Step 3)
659→    ///
660→    /// **Context**: Peer confirms sync complete after comparing vectors
661→    /// **Peer sends**: SyncAck with their final state vector
662→    /// **We do**: Update cached peer vector, log sync complete
663→    #[instrument(skip(self, state, their_state_vector), fields(page_id = %page_id, layer_name = %layer_name))]
664→    pub(in crate::peer_actor) async fn on_sync_ack(
665→        &self,
666→        page_id: &str,
667→        layer_name: &str,
668→        their_state_vector: &[u8],
669→        state: &mut PeerActorState<C>,
670→    ) {
671→        let (peer_did, _) = match require_auth(&state.state) {
672→            Ok(info) => (info.0.to_string(), info.1.to_string()),
673→            Err(_) => {
674→                warn!("SyncAck from unauthenticated peer: {}", self.node_id);
675→                return;
676→            }
677→        };
678→
679→        debug!(
680→            "SyncAck: page={} layer={} from {} - sync complete",
681→            page_id, layer_name, peer_did
682→        );
683→
684→        // Update Scribe's in-memory vector cache (persistence via periodic flush)
685→        let peer_device_id = self.node_id.to_string();
686→        if let Some(subscription) = state.page_subscriptions.get(page_id) {
687→            let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
688→                user_did: peer_did.clone(),
689→                device_id: peer_device_id.clone(),
690→                layer_name: layer_name.to_string(),
691→                state_vector: their_state_vector.to_vec(),
692→            });
693→
694→            if !Self::is_sync_meta_layer(page_id, layer_name) {
695→                if let Ok(user_info) = state.butler.user_info().await {
696→                    let sync_meta_layer = format!("__sync_meta/{}", user_info.did);
697→                    let sync_meta_key = layer_name
698→                        .strip_prefix(&format!("{}/", page_id))
699→                        .unwrap_or(layer_name)
700→                        .to_string();
701→                    let _ = subscription.scribe.cast(butler::ScribeMessage::MapInsert {
702→                        layer_name: sync_meta_layer,
703→                        path: String::new(),
704→                        key: sync_meta_key,
705→                        value: serde_json::json!({"synced": true, "version": 1}),
706→                    });
707→                }
708→            }
709→        }
710→
711→        // Clean up any pending sync for this page/layer (shouldn't exist but be safe)
712→        let key = (page_id.to_string(), layer_name.to_string());
713→        state.pending_sync_offers.remove(&key);
714→
715→        // Check if this is an assets layer sync - trigger asset fetch for missing blobs
716→        if layer_name == "assets" || layer_name.ends_with("/assets") {
717→            self.trigger_asset_sync_after_layer_sync(page_id, layer_name, state).await;
718→        }
719→    }
720→
721→    /// Handle incoming SyncReset from peer (fallback after max resyncs)
722→    ///
723→    /// **Context**: Peer exceeded MAX_RESYNC_ATTEMPTS OR explicitly needs layer snapshot.
724→    /// **Both modes**: Respond with SyncSnapshot when layer exists locally.
725→    #[instrument(skip(self, state), fields(page_id = %page_id, layer_name = %layer_name))]
726→    pub(in crate::peer_actor) async fn on_sync_reset(
727→        &self,
728→        page_id: &str,
729→        layer_name: &str,
730→        state: &mut PeerActorState<C>,
731→    ) {
732→        let peer_did = match require_auth(&state.state) {
733→            Ok((did, _)) => did.to_string(),
734→            Err(_) => {
735→                warn!("SyncReset from unauthenticated peer: {}", self.node_id);
736→                return;
737→            }
738→        };
739→
740→        info!(
741→            "SyncReset: page={} layer={} from {} - sending full snapshot",
742→            page_id, layer_name, peer_did
743→        );
744→
745→        // Get Scribe and export full snapshot
746→        let scribe = match state.butler.open_page(page_id).await {
747→            Ok(s) => s,
748→            Err(e) => {
749→                error!("Failed to open page {} for SyncReset: {}", page_id, e);
750→                return;
751→            }
752→        };
753→
754→        // Get full snapshot
755→        let (snapshot_tx, snapshot_rx) = tokio::sync::oneshot::channel();
756→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetSnapshot {
757→            layer_name: layer_name.to_string(),
758→            reply: snapshot_tx,
759→        }) {
760→            error!("Failed to request snapshot from Scribe: {}", e);
761→            return;
762→        }
763→
764→        let snapshot = match snapshot_rx.await {
765→            Ok(Some(data)) => data,
766→            Ok(None) => {
767→                warn!("Layer {} not found in Scribe for SyncReset", layer_name);
768→                return;
769→            }
770→            Err(_) => {
771→                error!("Scribe dropped snapshot reply channel");
772→                return;
773→            }
774→        };
775→
776→        // Get state vector
777→        let (vector_tx, vector_rx) = tokio::sync::oneshot::channel();
778→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetStateVector {
779→            layer_name: layer_name.to_string(),
780→            reply: vector_tx.into(),
781→        }) {
782→            error!("Failed to request state vector from Scribe: {}", e);
783→            return;
784→        }
785→
786→        let state_vector = match vector_rx.await {
787→            Ok(Ok(v)) => v,
788→            Ok(Err(e)) => {
789→                error!("Scribe returned error getting state vector: {}", e);
790→                return;
791→            }
792→            Err(_) => {
793→                error!("Scribe dropped state vector reply channel");
794→                return;
795→            }
796→        };
797→
798→        // Encrypt snapshot for transfer
799→        let peer_encryption_key = match state.peer_encryption_key {
800→            Some(key) => key,
801→            None => {
802→                warn!("Cannot send SyncSnapshot: peer encryption key not set");
803→                return;
804→            }
805→        };
806→
807→        let (ephemeral_public, encrypted_snapshot) = match herald::encrypt_for_transfer(
808→            &peer_encryption_key,
809→            &snapshot,
810→        ) {
811→            Ok(result) => result,
812→            Err(e) => {
813→                error!("Failed to encrypt snapshot: {}", e);
814→                return;
815→            }
816→        };
817→
818→        // Send SyncSnapshot
819→        let layer_name_owned = layer_name.to_string();
820→        let msg = Message::SyncSnapshot(SyncSnapshotMsg {
821→            page_id: page_id.to_string(),
822→            layer_type: LayerType::from_layer_name(&layer_name_owned),
823→            layer_name: layer_name_owned,
824→            snapshot: encrypted_snapshot,
825→            state_vector,
826→            ephemeral_public,
827→        });
828→        self.send_message(&msg, state).await;
829→
830→        info!(
831→            "Sent SyncSnapshot for page={} layer={} to {} ({} bytes)",
832→            page_id, layer_name, peer_did, snapshot.len()
833→        );
834→    }
835→
836→    /// Handle incoming SyncSnapshot from peer (response to SyncReset)
837→    ///
838→    /// **Context**: Peer responded to our SyncReset with a full snapshot.
839→    /// **Both modes**: Replace local layer with received state.
840→    #[instrument(skip(self, state, snapshot, their_state_vector, ephemeral_public), fields(page_id = %page_id, layer_name = %layer_name))]
841→    pub(in crate::peer_actor) async fn on_sync_snapshot(
842→        &self,
843→        page_id: &str,
844→        layer_name: &str,
845→        snapshot: &[u8],
846→        their_state_vector: &[u8],
847→        ephemeral_public: &[u8; 32],
848→        state: &mut PeerActorState<C>,
849→    ) {
850→        let peer_did = match require_auth(&state.state) {
851→            Ok((did, _)) => did.to_string(),
852→            Err(_) => {
853→                warn!("SyncSnapshot from unauthenticated peer: {}", self.node_id);
854→                return;
855→            }
856→        };
857→
858→        info!(
859→            "SyncSnapshot: page={} layer={} from {} ({} bytes) - replacing local state",
860→            page_id, layer_name, peer_did, snapshot.len()
861→        );
862→
863→        // Decrypt snapshot
864→        let our_secret = match state.butler.encryption_key().await {
865→            Ok(key) => key,
866→            Err(e) => {
867→                error!("Failed to get encryption key for SyncSnapshot decryption: {}", e);
868→                return;
869→            }
870→        };
871→
872→        let decrypted_snapshot = match herald::decrypt_from_transfer(&our_secret, ephemeral_public, snapshot) {
873→            Ok(data) => data,
874→            Err(e) => {
875→                error!("Failed to decrypt SyncSnapshot from {}: {}", peer_did, e);
876→                return;
877→            }
878→        };
879→
880→        // Get Scribe and replace layer
881→        let scribe = match state.butler.open_page(page_id).await {
882→            Ok(s) => s,
883→            Err(e) => {
884→                error!("Failed to open page {} for SyncSnapshot: {}", page_id, e);
885→                return;
886→            }
887→        };
888→
889→        // Replace layer with snapshot
890→        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
891→        if let Err(e) = scribe.cast(butler::ScribeMessage::ReplaceLayer {
892→            layer_name: layer_name.to_string(),
893→            snapshot: decrypted_snapshot,
894→            reply: reply_tx,
895→        }) {
896→            error!("Failed to send ReplaceLayer to Scribe: {}", e);
897→            return;
898→        }
899→
900→        match reply_rx.await {
901→            Ok(Ok(())) => {
902→                info!(
903→                    "SyncSnapshot applied: page={} layer={} - sync recovery complete",
904→                    page_id, layer_name
905→                );
906→
907→                if Self::is_sync_meta_layer(page_id, layer_name) {
908→                    self
909→                        .request_missing_layers_from_sync_meta(page_id, layer_name, &scribe, state)
910→                        .await;
911→                }
912→            }
913→            Ok(Err(e)) => {
914→                error!("ReplaceLayer failed for page={} layer={}: {}", page_id, layer_name, e);
915→                return;
916→            }
917→            Err(_) => {
918→                error!("Scribe dropped ReplaceLayer reply channel");
919→                return;
920→            }
921→        }
922→
923→        // Update Scribe's in-memory vector cache (persistence via periodic flush)
924→        let peer_device_id = self.node_id.to_string();
925→        if let Some(subscription) = state.page_subscriptions.get(page_id) {
926→            let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
927→                user_did: peer_did.clone(),
928→                device_id: peer_device_id,
929→                layer_name: layer_name.to_string(),
930→                state_vector: their_state_vector.to_vec(),
931→            });
932→
933→            if !Self::is_sync_meta_layer(page_id, layer_name) {
934→                if let Ok(user_info) = state.butler.user_info().await {
935→                    let sync_meta_layer = format!("__sync_meta/{}", user_info.did);
936→                    let sync_meta_key = layer_name
937→                        .strip_prefix(&format!("{}/", page_id))
938→                        .unwrap_or(layer_name)
939→                        .to_string();
940→                    let _ = subscription.scribe.cast(butler::ScribeMessage::MapInsert {
941→                        layer_name: sync_meta_layer,
942→                        path: String::new(),
943→                        key: sync_meta_key,
944→                        value: serde_json::json!({"synced": true, "version": 1}),
945→                    });
946→                }
947→            }
948→        }
949→
950→        // Clean up any pending sync
951→        let key = (page_id.to_string(), layer_name.to_string());
952→        state.pending_sync_offers.remove(&key);
953→    }
954→}
