359→/// Handle AddLayerAccess message
360→///
361→/// **Context**: Lua app calls scribe:add_layer_access(layer_name, did)
362→/// **We do**: Validate capability, require authority permit, issue permit if peer is subscribed
363→pub async fn handle_add_layer_access(
364→    state: &ScribeState,
365→    layer_name: &str,
366→    did: &str,
367→) -> Result<(), String> {
368→    // 1. Check our permit has manage_layer_access capability
369→    let permit = state.our_permit.as_ref().ok_or_else(|| {
370→        warn!(page_id = %state.page_id, layer = %layer_name, audience = %did, "AddLayerAccess rejected: missing our_permit");
371→        "No permit".to_string()
372→    })?;
373→    if !permit.can_manage_layer_access() {
374→        warn!(
375→            page_id = %state.page_id,
376→            layer = %layer_name,
377→            audience = %did,
378→            "AddLayerAccess rejected: missing manage_layer_access capability"
379→        );
380→        return Err("No manage_layer_access capability".into());
381→    }
382→
383→    // 2. Resolve schema/config and permit issuer
384→    let issuer = state.permit_issuer.as_ref().ok_or_else(|| {
385→        warn!(
386→            page_id = %state.page_id,
387→            layer = %layer_name,
388→            audience = %did,
389→            "AddLayerAccess rejected: no permit issuer (not node mode)"
390→        );
391→        "No permit issuer (not node mode)".to_string()
392→    })?;
393→    let (_schema_key, schema, _creator) = find_matching_dynamic_schema(permit, layer_name, &state.page_id)
394→        .ok_or_else(|| {
395→            warn!(
396→                page_id = %state.page_id,
397→                layer = %layer_name,
398→                audience = %did,
399→                "AddLayerAccess rejected: layer does not match dynamic schema"
400→            );
401→            "Layer does not match any dynamic schema".to_string()
402→        })?;
403→    if schema.grant != gurkha::GrantType::Explicit {
404→        warn!(
405→            page_id = %state.page_id,
406→            layer = %layer_name,
407→            audience = %did,
408→            "AddLayerAccess rejected: schema grant is not explicit"
409→        );
410→        return Err("AddLayerAccess only applies to explicit dynamic schemas".into());
411→    }
412→
413→    let (config, intent_cid, source) = if let Some((cfg, cid)) = authority_layer_config_and_intent(
414→        issuer.as_ref(),
415→        did,
416→        layer_name,
417→        &state.page_id,
418→    ) {
419→        (cfg, Some(cid), "authority")
420→    } else {
421→        let cfg = schema
422→            .permissions
423→            .clone()
424→            .ok_or_else(|| "Explicit schema missing permissions and no authority permit present".to_string())?;
425→        warn!(
426→            page_id = %state.page_id,
427→            layer = %layer_name,
428→            audience = %did,
429→            "No layer authority permit found; issuing access from explicit schema permissions"
430→        );
431→        (cfg, None, "schema_permissions")
432→    };
433→
434→    // 3. Issue permit (stored by coordinator even if peer is offline)
435→    let mut new_permits = Vec::new();
436→    match issuer.issue_layer_permit(did, layer_name, config, intent_cid.as_deref()) {
437→        Ok((token, _cid)) => {
438→            info!(
439→                page_id = %state.page_id,
440→                layer = %layer_name,
441→                audience = %did,
442→                source = %source,
443→                "Issued layer permit via AddLayerAccess"
444→            );
445→            new_permits.push((did.to_string(), token));
446→        }
447→        Err(e) => {
448→            warn!(error = %e, "Failed to issue layer permit for AddLayerAccess");
449→        }
450→    }
451→
452→    // 4. Authorize DID on the LayerUnit (if permit was issued)
453→    if let Some((recipient_did, _token)) = new_permits.first() {
454→        let bare_name = crate::state::normalize_layer_name(layer_name, &state.page_id);
455→        if let Some(unit) = state.units.get(&bare_name) {
456→            unit.authorize_did(recipient_did);
457→            state.emit_layer_auth_capture(&bare_name, recipient_did, "authorized_add_access");
458→        }
459→    }
460→
461→    // 5. Emit LayerAccessChanged for Coordinator to store/distribute permit
462→    if !new_permits.is_empty() {
463→        if let Some(ref sync_event_tx) = state.sync_event_tx {
464→            let event = crate::SyncEvent::LayerAccessChanged {
465→                page_id: state.page_id.clone(),
466→                layer_name: layer_name.to_string(),
467→                permits: new_permits,
468→            };
469→            state.emit_sync_event_capture(&event);
470→            if let Err(e) = sync_event_tx.send(event).await {
471→                warn!(error = %e, "Failed to emit LayerAccessChanged");
472→            }
473→        }
474→    }
475→
476→    Ok(())
477→}
