357→    async fn handle_supervisor_evt(
358→        &self,
359→        _myself: ActorRef<Self::Msg>,
360→        event: SupervisionEvent,
361→        state: &mut Self::State,
362→    ) -> Result<(), ActorProcessingErr> {
363→        match event {
364→            SupervisionEvent::ActorStarted(cell) => {
365→                debug!("Child actor started: {:?}", cell.get_id());
366→            }
367→            SupervisionEvent::ActorTerminated(cell, _, reason) => {
368→                debug!(
369→                    "Child actor {} terminated: {:?}",
370→                    cell.get_id(),
371→                    reason
372→                );
373→                // Find and remove from unified registry
374→                state.peers.retain(|node_id, entry| {
375→                    if entry.actor.get_id() == cell.get_id() {
376→                        debug!("Removing terminated PeerActor {}", node_id);
377→                        false
378→                    } else {
379→                        true
380→                    }
381→                });
382→            }
383→            SupervisionEvent::ActorFailed(cell, error) => {
384→                error!("Child actor {} failed: {}", cell.get_id(), error);
385→                // Same cleanup as terminated
386→                state.peers.retain(|node_id, entry| {
387→                    if entry.actor.get_id() == cell.get_id() {
388→                        debug!("Removing failed PeerActor {}", node_id);
389→                        false
390→                    } else {
391→                        true
392→                    }
393→                });
394→            }
395→            _ => {}
396→        }
397→
398→        Ok(())
399→    }
400→}
