591→    /// Find peer actor for a user by DID
592→    fn get_peer_actor_for_user<'a>(
593→        &self,
594→        user_did: &str,
595→        state: &'a CoordinatorState<C>,
596→    ) -> Option<&'a ActorRef<PeerMessage>> {
597→        state.authenticated_peers()
598→            .find(|(_, entry)| entry.auth.as_ref().map(|a| a.did.as_str()) == Some(user_did))
599→            .map(|(_, entry)| &entry.actor)
600→    }
