  1→//! Loro CRDT observer and delta handling
  2→//!
  3→//! Handles subscription to Loro changes, delta conversion, and reactive notifications.
  4→//!
  5→//! **Architecture**: Loro's `import()` triggers `subscribe_root` observers automatically.
  6→//! We set up observers for all layers at startup so that both UI notifications and
  7→//! peer broadcasts are handled through the observer pattern (no manual callbacks needed).
  8→
  9→use loro::event::{Diff, DiffEvent, ListDiffItem};
 10→use loro::{LoroValue, ValueOrContainer};
 11→use tokio::sync::mpsc;
 12→use tracing::{debug, info, instrument, warn};
 13→use base64::Engine;
 14→
 15→use crate::message::{BroadcastPayload, LoroDelta, ListOp, PageUpdate};
 16→use crate::permit::Permissions;
 17→use crate::state::ScribeState;
 18→use domains::JsonOp;
 19→
 20→/// Data sent through observer channel (delta + ops for reactive bindings)
 21→struct ObserverSignal {
 22→    delta: Option<LoroDelta>,
 23→    ops: Vec<JsonOp>,
 24→    /// Source of the change: None = local, Some = remote peer (user_did, device_id)
 25→    /// Used for sender exclusion in broadcasts
 26→    from_peer: Option<(String, String)>,
 27→}
 28→
 29→// Delta Conversion Helpers
 30→
 31→/// Convert DiffEvent to structured JsonOps for reactive bindings
 32→///
 33→/// **Context**: Observer receives DiffEvent on Loro changes
 34→/// **We do**: Extract structured ops (insert/update/delete) with keys/values
 35→/// **Used by**: Lua's on_loro_change(layer, ops, full_data) for surgical UI updates
 36→pub fn diff_event_to_ops(diff_event: &DiffEvent) -> Vec<JsonOp> {
 37→    let mut ops = Vec::new();
 38→
 39→    for container_diff in &diff_event.events {
 40→        let path = container_diff.target.to_string();
 41→
 42→        match &container_diff.diff {
 43→            Diff::List(items) => {
 44→                // Track position for list operations
 45→                let mut pos = 0usize;
 46→                for item in items.iter() {
 47→                    match item {
 48→                        ListDiffItem::Insert { insert, .. } => {
 49→                            for (i, value) in insert.iter().enumerate() {
 50→                                let json_value = value_or_container_to_json(value);
 51→                                ops.push(JsonOp {
 52→                                    op: "insert".to_string(),
 53→                                    path: path.clone(),
 54→                                    key: None,
 55→                                    index: Some(pos + i),
 56→                                    value: Some(json_value),
 57→                                    old_value: None,
 58→                                });
 59→                            }
 60→                            pos += insert.len();
 61→                        }
 62→                        ListDiffItem::Delete { delete } => {
 63→                            // Each delete is a single op
 64→                            for _ in 0..*delete {
 65→                                ops.push(JsonOp {
 66→                                    op: "delete".to_string(),
 67→                                    path: path.clone(),
 68→                                    key: None,
 69→                                    index: Some(pos),
 70→                                    value: None,
 71→                                    old_value: None,
 72→                                });
 73→                            }
 74→                            // Position doesn't advance for deletes
 75→                        }
 76→                        ListDiffItem::Retain { retain } => {
 77→                            // Retain just moves position, no op
 78→                            pos += retain;
 79→                        }
 80→                    }
 81→                }
 82→            }
 83→
 84→            Diff::Map(map_delta) => {
 85→                for (key, value) in map_delta.updated.iter() {
 86→                    let json_value = value.as_ref()
 87→                        .map(|v| value_or_container_to_json(v));
 88→
 89→                    if let Some(val) = json_value {
 90→                        // Could be insert or update - we use "set" for both
 91→                        ops.push(JsonOp {
 92→                            op: "set".to_string(),
 93→                            path: path.clone(),
 94→                            key: Some(key.to_string()),
 95→                            index: None,
 96→                            value: Some(val),
 97→                            old_value: None,  // TODO: Could track old values if needed
 98→                        });
 99→                    } else {
100→                        // Value is None = deletion
101→                        ops.push(JsonOp {
102→                            op: "delete".to_string(),
103→                            path: path.clone(),
104→                            key: Some(key.to_string()),
105→                            index: None,
106→                            value: None,
107→                            old_value: None,
108→                        });
109→                    }
110→                }
111→            }
112→
113→            Diff::Text(_text_delta) => {
114→                // Text deltas not yet supported for ops
115→                debug!("Text ops not yet implemented");
116→            }
117→
118→            _ => {
119→                debug!("Unsupported diff type for ops: {:?}", container_diff.diff);
120→            }
121→        }
122→    }
123→
124→    ops
125→}
126→
127→/// Convert Loro's Diff to our LoroDelta format
128→///
129→/// **Context**: Loro observer provides Diff on changes, we convert to JSON-serializable format
130→/// **Returns**: LoroDelta for List/Map/Text containers, None for unsupported types
131→pub fn convert_loro_diff_to_delta(diff: &Diff) -> Option<LoroDelta> {
132→    match diff {
133→        Diff::List(items) => {
134→            let ops = items.iter().map(|item| {
135→                match item {
136→                    ListDiffItem::Insert { insert, .. } => {
137→                        // Convert ValueOrContainer to JSON values
138→                        let values = insert.iter()
139→                            .map(|v| value_or_container_to_json(v))
140→                            .collect();
141→                        ListOp::Insert { values }
142→                    }
143→                    ListDiffItem::Delete { delete } => {
144→                        ListOp::Delete { count: *delete }
145→                    }
146→                    ListDiffItem::Retain { retain } => {
147→                        ListOp::Retain { count: *retain }
148→                    }
149→                }
150→            }).collect();
151→
152→            Some(LoroDelta::List { ops })
153→        }
154→
155→        Diff::Map(map_delta) => {
156→            let updated = map_delta.updated.iter()
157→                .map(|(k, v)| {
158→                    let value = v.as_ref()
159→                        .map(|v| value_or_container_to_json(v));
160→                    (k.to_string(), value)
161→                })
162→                .collect();
163→
164→            Some(LoroDelta::Map { updated })
165→        }
166→
167→        Diff::Text(_text_delta) => {
168→            // TODO: Implement text delta conversion when needed
169→            // For now, return None and fall back to full data
170→            debug!("Text delta conversion not yet implemented");
171→            None
172→        }
173→
174→        _ => {
175→            debug!("Unsupported diff type: {:?}", diff);
176→            None
177→        }
178→    }
179→}
180→
181→/// Convert Loro ValueOrContainer to serde_json::Value
182→///
183→/// **Context**: Loro stores values as LoroValue or nested Containers
184→/// **We do**: Extract deep value and convert to JSON
185→fn value_or_container_to_json(value: &ValueOrContainer) -> serde_json::Value {
186→    // Use ValueOrContainer::get_deep_value() to resolve containers
187→    let deep_value = value.get_deep_value();
188→    loro_value_to_json(&deep_value)
189→}
190→
191→/// Convert LoroValue to serde_json::Value
192→///
193→/// **Context**: Loro's native value type → JSON for Lua consumption
194→pub fn loro_value_to_json(value: &LoroValue) -> serde_json::Value {
195→    match value {
196→        LoroValue::Null => serde_json::Value::Null,
197→        LoroValue::Bool(b) => serde_json::Value::Bool(*b),
198→        LoroValue::I64(i) => serde_json::json!(*i),
199→        LoroValue::Double(f) => serde_json::json!(*f),
200→        LoroValue::String(s) => serde_json::Value::String(s.to_string()),
201→        LoroValue::List(arr) => {
202→            serde_json::Value::Array(
203→                arr.iter().map(loro_value_to_json).collect()
204→            )
205→        }
206→        LoroValue::Map(map) => {
207→            serde_json::Value::Object(
208→                map.iter()
209→                    .map(|(k, v)| (k.to_string(), loro_value_to_json(v)))
210→                    .collect()
211→            )
212→        }
213→        LoroValue::Binary(bytes) => {
214→            // Encode binary as base64 string
215→            serde_json::Value::String(base64::engine::general_purpose::STANDARD.encode(&**bytes))
216→        }
217→        LoroValue::Container(_) => {
218→            // Containers are resolved by get_deep_value, shouldn't appear in deltas
219→            debug!("Container in delta value (unexpected), converting to null");
220→            serde_json::Value::Null
221→        }
222→    }
223→}
224→
225→// Loro Layer Handler
226→
227→/// Handle layer modified by Lua via direct FFI access
228→///
229→/// **Context**: Lua called push/set/etc on a LoroList/LoroMap
230→/// **We do**: Check permission, commit transaction, let Loro observer handle notifications
231→///
232→/// **Note**: By the time this is called, the change is already in the Loro doc (via FFI).
233→/// We can't reject it here, but we log a warning if permission would be denied.
234→/// Future: Lua bindings should check can_local_write() before allowing the operation.
235→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
236→pub async fn handle_layer_modified_by_lua(state: &mut ScribeState, layer_name: String) {
237→    debug!(layer_name = %layer_name, "Layer modified by Lua, committing transaction");
238→
239→    // Check if we have permission to write to this layer
240→    // Note: Changes are already made via FFI, this is defense-in-depth logging
241→    if !Permissions::can_local_write(state, &layer_name) {
242→        warn!(
243→            layer = %layer_name,
244→            our_did = %state.our_did,
245→            "Local write to layer without permission (changes already applied via FFI)"
246→        );
247→        // TODO: In future, Lua bindings should check permission before allowing write
248→        // For now, we still commit to avoid leaving Loro in inconsistent state
249→    }
250→
251→    // Commit the Loro transaction to trigger native observer
252→    // This makes the observer fire immediately with delta information
253→    if let Some(unit) = state.units.get(&layer_name) {
254→        unit.layer().commit();
255→    }
256→
257→    // Mark layer as dirty for periodic flush (every 10s)
258→    if let Some(unit) = state.units.get_mut(&layer_name) {
259→        unit.mark_dirty();
260→    }
261→
262→    // NOTE: We don't manually notify observers here!
263→    // The commit() above triggers Loro's native observer (setup in handle_subscribe_loro_changes)
264→    // which will automatically:
265→    // - Send LoroChangeEvent with delta to UI
266→    // - Notify query subscribers
267→    // - Broadcast to peers
268→    //
269→    // Dirty layer will be flushed to storage by periodic timer (every 10s)
270→}
271→
272→// Startup Observer Setup
273→
274→/// Set up Loro observers for all layers at Scribe startup
275→///
276→/// **Context**: Called from `pre_start` to ensure observers are ready before any updates
277→/// **Why**: Loro's `import()` triggers observers automatically, so we need them set up
278→/// **Handles**: Peer broadcasts (to subscribers) + UI notifications (to loro_observers)
279→///
280→/// This ensures both local changes (via commit) and remote changes (via import)
281→/// go through the same observer-based notification path.
282→#[instrument(skip_all, fields(page_id = %state.page_id))]
283→pub fn setup_observers_for_all_layers(state: &mut ScribeState) {
284→    let layer_names: Vec<String> = state.units.keys().cloned().collect();
285→
286→    for layer_name in layer_names {
287→        setup_layer_observer(state, &layer_name);
288→    }
289→
290→    let observer_count = state.units.values().filter(|u| u.has_observer()).count();
291→    info!(
292→        page_id = %state.page_id,
293→        layer_count = observer_count,
294→        "Set up Loro observers for all layers"
295→    );
296→}
297→
298→/// Set up Loro observer for a single layer
299→///
300→/// **Context**: Sets up the observer infrastructure for peer broadcasts and UI notifications
301→/// **Observer fires**: On commit() AND import() - both trigger subscribe_root
302→///
303→/// **Public**: Called from mod.rs when new layers are dynamically created
304→#[instrument(skip(state), fields(page_id = %state.page_id))]
305→pub fn setup_layer_observer(state: &mut ScribeState, layer_name: &str) {
306→    // Skip if already set up
307→    match state.units.get(layer_name) {
308→        Some(u) if u.has_observer() => return,
309→        Some(_) => {}
310→        None => {
311→            warn!(layer_name = %layer_name, "Layer not found for observer setup");
312→            return;
313→        }
314→    };
315→
316→    // We need to get the layer clone and is_local_only before borrowing state mutably
317→    let (layer_clone, is_local_only) = {
318→        let unit = state.units.get(layer_name).unwrap();
319→        (unit.layer().clone(), unit.is_local_only())
320→    };
321→
322→    // Create internal channel for observer signals (includes ops for reactive bindings)
323→    let (signal_tx, mut signal_rx) = tokio::sync::mpsc::unbounded_channel::<ObserverSignal>();
324→
325→    // Clone for the async task
326→    let layer_for_task = layer_clone.clone();
327→    let layer_name_for_task = layer_name.to_string();
328→    let subscribers_for_task = state.subscribers.clone();
329→    let page_id_for_task = state.page_id.clone();
330→    let page_update_subscribers_for_task = state.page_update_subscribers.clone();
331→    // Capture authorized_dids Arc for broadcast filtering
332→    let authorized_dids_for_task = state.units.get(layer_name).unwrap().authorized_dids().clone();
333→    // Clone capture_tx for the observer task
334→    let capture_tx_for_task = state.capture_tx.clone();
335→
336→    // Clone pending_update_source for the synchronous callback
337→    let pending_update_source = state.pending_update_source.clone();
338→
339→    // Spawn async task to handle observer signals
340→    // Note: Derivation is handled in handle_apply_update using ops, not here
341→    tokio::spawn(async move {
342→        while let Some(signal) = signal_rx.recv().await {
343→            let state_vector = layer_for_task.version_vector();
344→
345→            // Prepare ops for reactive bindings (Some if non-empty, None otherwise)
346→            let ops = if signal.ops.is_empty() { None } else { Some(signal.ops) };
347→
348→            // Skip expensive get_content() only for List deltas (surgical conversion always works).
349→            // For Map/Text deltas, always provide full_data so non-keyed Map bindings can
350→            // fall back to Replace when delta conversion returns empty.
351→            let full_data = if matches!(&signal.delta, Some(LoroDelta::List { .. })) {
352→                None
353→            } else {
354→                Some(layer_for_task.get_content(&layer_name_for_task))
355→            };
356→
357→            let page_update = PageUpdate::LayerChanged {
358→                layer: layer_name_for_task.clone(),
359→                from_peer: None,  // Local change
360→                ops,
361→                delta: signal.delta,
362→                state_vector,
363→                full_data,
364→                created: false,
365→            };
366→            // Emit to capture channel (pre-serialized JSON line)
367→            if let Some(ref capture_tx) = capture_tx_for_task {
368→                let ts = std::time::SystemTime::now()
369→                    .duration_since(std::time::UNIX_EPOCH)
370→                    .map(|d| d.as_millis())
371→                    .unwrap_or(0);
372→                if let Ok(json) = serde_json::to_string(&serde_json::json!({
373→                    "type": "page_update",
374→                    "ts": ts,
375→                    "page_id": &page_id_for_task,
376→                    "data": &page_update,
377→                })) {
378→                    let _ = capture_tx.send(json);
379→                }
380→            }
381→            if let Ok(subs) = page_update_subscribers_for_task.read() {
382→                for tx in subs.iter() {
383→                    let _ = tx.try_send(page_update.clone());
384→                }
385→                if !subs.is_empty() {
386→                    debug!(
387→                        layer_name = %layer_name_for_task,
388→                        subscriber_count = subs.len(),
389→                        "Sent PageUpdate::LayerChanged"
390→                    );
391→                }
392→            }
393→
394→            // Check if layer is local-only (sync: false in permit)
395→            // Captured as bool at observer setup time — static per layer
396→            if is_local_only {
397→                if let Some(ref ctx) = capture_tx_for_task {
398→                    let ts = std::time::SystemTime::now()
399→                        .duration_since(std::time::UNIX_EPOCH)
400→                        .map(|d| d.as_millis())
401→                        .unwrap_or(0);
402→                    let _ = ctx.send(serde_json::json!({
403→                        "type": "broadcast_decision",
404→                        "ts": ts,
405→                        "page_id": &page_id_for_task,
406→                        "layer": &layer_name_for_task,
407→                        "decision": "skip",
408→                        "reason": "local_only",
409→                    }).to_string());
410→                }
411→                debug!(
412→                    layer_name = %layer_name_for_task,
413→                    "Skipping peer broadcast for local-only layer (sync: false)"
414→                );
415→                continue;
416→            }
417→
418→            // Skip peer broadcast for remote updates (sender exclusion)
419→            // Remote updates are forwarded via broadcast_update() in apply.rs which has proper sender exclusion
420→            // Broadcasting here would send the update back to the original sender, causing a sync storm
421→            if signal.from_peer.is_some() {
422→                if let Some(ref ctx) = capture_tx_for_task {
423→                    let ts = std::time::SystemTime::now()
424→                        .duration_since(std::time::UNIX_EPOCH)
425→                        .map(|d| d.as_millis())
426→                        .unwrap_or(0);
427→                    let _ = ctx.send(serde_json::json!({
428→                        "type": "broadcast_decision",
429→                        "ts": ts,
430→                        "page_id": &page_id_for_task,
431→                        "layer": &layer_name_for_task,
432→                        "decision": "skip",
433→                        "reason": "remote_handled_by_apply",
434→                    }).to_string());
435→                }
436→                debug!(
437→                    layer_name = %layer_name_for_task,
438→                    "Skipping observer peer broadcast for remote update (handled by broadcast_update)"
439→                );
440→                continue;
441→            }
442→
443→            // Broadcast incremental updates to peer subscribers
444→            // Uses per-subscriber export_updates(their_vector) instead of full snapshot
445→            let current_vector = layer_for_task.version_vector();
446→
447→            if let Ok(subs) = subscribers_for_task.read() {
448→                debug!(
449→                    page_id = %page_id_for_task,
450→                    layer_name = %layer_name_for_task,
451→                    subscriber_count = subs.len(),
452→                    "Observer broadcasting to subscribers"
453→                );
454→                let authorized = authorized_dids_for_task.read().unwrap_or_else(|e| e.into_inner());
455→                for ((user_did, device_id), info) in subs.iter() {
456→                    if !authorized.contains(user_did) {
457→                        if let Some(ref ctx) = capture_tx_for_task {
458→                            let ts = std::time::SystemTime::now()
459→                                .duration_since(std::time::UNIX_EPOCH)
460→                                .map(|d| d.as_millis())
461→                                .unwrap_or(0);
462→                            let _ = ctx.send(serde_json::json!({
463→                                "type": "broadcast_decision",
464→                                "ts": ts,
465→                                "page_id": &page_id_for_task,
466→                                "layer": &layer_name_for_task,
467→                                "peer_did": user_did,
468→                                "decision": "skip",
469→                                "reason": "not_authorized",
470→                            }).to_string());
471→                        }
472→                        continue;
473→                    }
474→
475→                    // Incremental export: use subscriber's last known vector
476→                    // Falls back to full snapshot for first sync (no vector cached)
477→                    let update = if let Some(their_vector) = info.vectors.get(&*layer_name_for_task) {
478→                        layer_for_task.export_updates(their_vector)
479→                            .unwrap_or_else(|_| layer_for_task.export_snapshot())
480→                    } else {
481→                        layer_for_task.export_snapshot()
482→                    };
483→
484→                    let update_size = update.len();
485→                    let payload = BroadcastPayload {
486→                        page_id: page_id_for_task.clone(),
487→                        layer_name: layer_name_for_task.clone(),
488→                        layer_type: domains::LayerType::from_layer_name(&layer_name_for_task),
489→                        update,
490→                        state_vector: current_vector.clone(),
491→                    };
492→
