  1→//! Broadcast handling for Scribe actor
  2→//!
  3→//! Handles layer update broadcasting to subscribers and page update emission.
  4→
  5→use tokio::sync::mpsc;
  6→use tracing::{info, instrument, warn};
  7→
  8→use crate::message::{BroadcastPayload, PageUpdate};
  9→use crate::state::ScribeState;
 10→
 11→// Layer Broadcasting
 12→
 13→/// Broadcast layer update to all eligible subscribers
 14→///
 15→/// **Context**: Layer has been updated, notify all subscribers
 16→/// **We do**: Send incremental or full snapshot to each subscriber
 17→/// **Cleanup**: Remove subscribers whose channels are closed (disconnected)
 18→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
 19→pub async fn broadcast_update(
 20→    state: &mut ScribeState,
 21→    layer_name: &str,
 22→    from_peer: Option<&(String, String)>,
 23→) {
 24→    let Some(unit) = state.units.get(layer_name) else {
 25→        return;
 26→    };
 27→
 28→    let current_vector = unit.layer().version_vector();
 29→    let layer = unit.layer().clone(); // Clone for use inside subscriber lock
 30→
 31→    // Read authorized_dids once before the subscriber loop
 32→    let authorized = unit.authorized_dids().read().unwrap_or_else(|e| e.into_inner()).clone();
 33→
 34→    // Track subscribers to remove (channel closed = peer disconnected)
 35→    let mut to_remove: Vec<(String, String)> = Vec::new();
 36→
 37→    if let Ok(mut subs) = state.subscribers.write() {
 38→        for ((user_did, device_id), info) in subs.iter_mut() {
 39→            // Skip sender
 40→            if from_peer == Some(&(user_did.clone(), device_id.clone())) {
 41→                state.emit_broadcast_decision_capture(layer_name, user_did, "skip_sender");
 42→                continue;
 43→            }
 44→
 45→            // Check authorization via LayerUnit
 46→            if !authorized.contains(user_did) {
 47→                state.emit_broadcast_decision_capture(layer_name, user_did, "not_authorized");
 48→                continue;
 49→            }
 50→
 51→            // Incremental export: use subscriber's last known vector
 52→            // Falls back to full snapshot for first sync (no vector cached)
 53→            let update = if let Some(their_vector) = info.vectors.get(layer_name) {
 54→                layer.export_updates(their_vector)
 55→                    .unwrap_or_else(|_| layer.export_snapshot())
 56→            } else {
 57→                layer.export_snapshot()
 58→            };
 59→
 60→            let payload = BroadcastPayload {
 61→                page_id: state.page_id.clone(),
 62→                layer_name: layer_name.to_string(),
 63→                layer_type: domains::LayerType::from_layer_name(layer_name),
 64→                update,
 65→                state_vector: current_vector.clone(),
 66→            };
 67→
 68→            match info.broadcast_tx.try_send(payload) {
 69→                Ok(()) => {
 70→                    // Update their vector on successful send
 71→                    info.vectors.insert(layer_name.to_string(), current_vector.clone());
 72→                }
 73→                Err(mpsc::error::TrySendError::Closed(_)) => {
 74→                    info!(user_did = %user_did, device_id = %device_id, "Subscriber disconnected, removing");
 75→                    to_remove.push((user_did.clone(), device_id.clone()));
 76→                }
 77→                Err(mpsc::error::TrySendError::Full(_)) => {
 78→                    warn!(user_did = %user_did, "Broadcast channel full, update dropped");
 79→                }
 80→            }
 81→        }
 82→
 83→        // Remove disconnected subscribers
 84→        for key in to_remove {
 85→            if let Some(info) = subs.remove(&key) {
 86→                if let Err(e) = state.vector_storage.save_vectors(&key.0, &key.1, &info.vectors) {
 87→                    warn!(error = %e, user_did = %key.0, device_id = %key.1, "Failed to save peer vector on disconnect");
 88→                }
 89→                info!(user_did = %key.0, device_id = %key.1, "Cleaned up disconnected subscriber");
 90→            }
 91→        }
 92→    }
 93→
 94→    // Emit EnsureSync for any sync targets not currently subscribed
 95→    super::reconcile::emit_sync_events_for_missing_targets(state);
 96→}
 97→
 98→// Page Update Emission
 99→
100→/// Notify page event subscribers of new layer discovery
101→///
102→/// **Context**: A new layer was created (from peer sync or local creation)
103→/// **We do**: Send PageUpdate::LayerChanged with created=true to unified subscribers
104→#[instrument(skip(state), fields(page_id = %state.page_id, layer = %layer_name))]
105→pub fn notify_layer_discovered(state: &ScribeState, layer_name: &str) {
106→    let full_data = state.units.get(layer_name)
107→        .map(|unit| unit.layer().get_content(layer_name))
108→        .unwrap_or(serde_json::Value::Null);
109→
110→    let state_vector = state.units.get(layer_name)
111→        .map(|unit| unit.layer().version_vector())
112→        .unwrap_or_default();
113→
114→    let update = PageUpdate::LayerChanged {
115→        layer: layer_name.to_string(),
116→        from_peer: None,
117→        ops: None,
118→        delta: None,
119→        state_vector: state_vector.clone(),
120→        full_data: Some(full_data.clone()),
121→        created: true,
122→    };
123→    state.emit_page_update_capture(&update);
124→    if let Ok(subs) = state.page_update_subscribers.read() {
125→        for tx in subs.iter() {
126→            let _ = tx.try_send(update.clone());
127→        }
128→    }
129→}
