        layer_name: layer_name_owned,
        snapshot: encrypted_snapshot,
        state_vector,
        ephemeral_public,
    });
    self.send_message(&msg, state).await;

    info!(
        "Sent SyncSnapshot for page={} layer={} to {} ({} bytes)",
        page_id, layer_name, peer_did, snapshot.len()
