/// Detect if a newly created layer matches a dynamic schema, write sync_meta entries,
/// and emit permits for distribution.
///
/// **Context**: Node receives a new layer from peer. If it matches a dynamic schema,
/// prepare layer permits for authorized peers and write sync_meta entries for discovery.
/// **Offline-first**: Peers discover new layers via `__sync_meta/{their_did}` entries,
/// NOT via direct broadcast authorization. Same mechanism works for online and offline peers.
/// **Coordinator** distributes the layer permits to PeerActors → peers for storage.
#[instrument(skip(state), fields(page_id = %state.page_id, layer = %layer_name))]
async fn emit_dynamic_layer_permits(
    state: &mut ScribeState,
    layer_name: &str,
    from_peer: &(String, String),
) {
    // Only nodes issue permits (require permit_issuer + our_permit + sync_event_tx)
    let Some(ref permit_issuer) = state.permit_issuer else { return; };
    let Some(ref our_permit) = state.our_permit else { return; };
    let Some(ref sync_event_tx) = state.sync_event_tx else { return; };

    // Check if layer matches a dynamic schema
    let Some((schema_key, schema, creator_did)) =
        find_matching_dynamic_schema(our_permit, layer_name, &state.page_id) else { return; };

    // Validate creator namespace: sender's DID must match DID in path
    if from_peer.0 != creator_did {
        warn!(
            layer = %layer_name,
            sender = %from_peer.0,
            creator = %creator_did,
            "Creator namespace mismatch — sender DID doesn't match path DID"
        );
        return;
    }

    // Collect connected peers with their roles
    let connected_peers = collect_connected_peers_with_roles(state);

    // Prepare layer permits
    let full_layer_name = format!("{}/{}", state.page_id, layer_name);
    match prepare_layer_permits(
        permit_issuer.as_ref(),
        &state.page_id,
        &full_layer_name,
        schema,
        &creator_did,
        &connected_peers,
    ) {
        Ok(permits) if !permits.is_empty() => {
            info!(
                layer = %layer_name,
                schema = %schema_key,
                creator = %creator_did,
                permit_count = permits.len(),
                "Prepared dynamic layer permits, writing sync_meta entries for discovery"
            );

            // Write __sync_meta/{recipient_did}[layer_name] = {synced: false} for each recipient.
            // This is how peers discover new dynamic layers (offline-first).
            for (recipient_did, _token) in &permits {
                write_sync_meta_entry(state, recipient_did, layer_name);
                state.emit_layer_auth_capture(layer_name, recipient_did, "sync_meta_written");
                debug!(
                    recipient = %recipient_did,
                    layer = %layer_name,
                    "Wrote sync_meta entry for dynamic layer discovery"
                );
            }

            let event = SyncEvent::NewDynamicLayer {
                page_id: state.page_id.clone(),
                layer_name: full_layer_name,
                permits,
            };

            state.emit_sync_event_capture(&event);
            if let Err(e) = sync_event_tx.send(event).await {
                error!(error = %e, "Failed to emit NewDynamicLayer event");
            }
        }
        Ok(_) => {
            debug!(layer = %layer_name, "No permits needed for dynamic layer");
        }
        Err(e) => {
            error!(layer = %layer_name, error = %e, "Failed to prepare dynamic layer permits");
        }
    }
}

/// Write a sync_meta entry for a recipient peer to discover a layer.
///
/// **Context**: Node detected a new dynamic layer and needs to notify a peer.
/// **We write**: `__sync_meta/{recipient_did}[layer_name] = {synced: false, version: 1}`
/// **Why**: The sync_meta layer syncs to the peer, who discovers the entry and requests the layer.
fn write_sync_meta_entry(state: &mut ScribeState, recipient_did: &str, layer_name: &str) {
    use crate::state::json_to_loro_value;

    let sync_meta_layer = format!("__sync_meta/{}", recipient_did);
    let created = if !state.units.contains_key(&sync_meta_layer) {
        let mut unit = LayerUnit::new_empty();
        unit.set_local_only(false);
        state.units.insert(sync_meta_layer.clone(), unit);
        true
    } else {
        false
    };

    if let Some(unit) = state.units.get_mut(&sync_meta_layer) {
        let map = unit.layer().loro().get_map(sync_meta_layer.as_str());
        if map
            .insert(
                layer_name,
                json_to_loro_value(&serde_json::json!({"synced": false, "version": 1})),
            )
            .is_ok()
        {
            unit.layer().commit();
            unit.mark_dirty();
        }
    }

    if created {
        setup_layer_observer(state, &sync_meta_layer);
    }
}

