/// Distribute layer permits and write sync_meta entries for discovery
///
/// **Context**: Scribe detected a new dynamic layer → issued permits → NewDynamicLayer event
/// **We do**: Store permits in butler, send to PeerActors, write __sync_meta/{viewer_did}
/// **Offline-first**: sync_meta entries are the discovery mechanism. Viewers read their
/// sync_meta, find synced=false entries, and request missing layers via SyncReset.
async fn on_distribute_layer_permits(
    &self,
    page_id: &str,
    layer_name: &str,
    permits: &[(String, String)],
    state: &mut CoordinatorState<C>,
) {
    info!(
        "Distributing {} layer permits for page={} layer={}",
        permits.len(), page_id, layer_name
    );

    // Open scribe once for writing sync_meta entries
    let scribe = match state.butler.open_page(page_id).await {
        Ok(s) => Some(s),
        Err(e) => {
            warn!(error = %e, "Failed to open page for sync_meta fanout");
            None
        }
    };

    // Strip page_id/ prefix for the sync_meta key
    let sync_meta_key = layer_name
        .strip_prefix(&format!("{}/", page_id))
        .unwrap_or(layer_name)
        .to_string();

    for (recipient_did, permit_token) in permits {
        // Store layer permit in butler
        if let Err(e) = state.butler.permits().store_layer_permit(
            page_id,
            recipient_did,
            layer_name,
            permit_token,
        ) {
            warn!(
                recipient = %recipient_did,
                error = %e,
                "Failed to store layer permit"
            );
            continue;
        }

        // Write __sync_meta/{recipient_did}[layer_name] = {synced: false}
        // This is how the viewer discovers the new dynamic layer (offline-first)
        if let Some(ref scribe) = scribe {
            let sync_meta_layer = format!("__sync_meta/{}", recipient_did);
            if let Err(e) = scribe.cast(butler::ScribeMessage::MapInsert {
                layer_name: sync_meta_layer,
                path: String::new(),
                key: sync_meta_key.clone(),
                value: serde_json::json!({"synced": false, "version": 1}),
            }) {
                warn!(
                    recipient = %recipient_did,
                    error = %e,
                    "Failed to write sync_meta entry for dynamic layer"
                );
            } else {
                info!(
                    recipient = %recipient_did,
                    layer = %layer_name,
                    "Wrote sync_meta entry for dynamic layer discovery"
                );
            }
        }

        // Find PeerActor for this recipient and send
        if let Some(actor) = state.get_peer_actor_for_did(recipient_did) {
            if let Err(e) = actor.cast(PeerMessage::SendLayerPermit {
                page_id: page_id.to_string(),
                layer_name: layer_name.to_string(),
                permit: permit_token.clone(),
            }) {
                warn!(
                    recipient = %recipient_did,
                    error = %e,
                    "Failed to send LayerPermit to PeerActor"
                );
            } else {
                info!(recipient = %recipient_did, "Sent LayerPermit to PeerActor");
            }
        } else {
            // Peer not connected — permit stored + sync_meta written, will sync on reconnect
            debug!(
                recipient = %recipient_did,
                "Peer not connected, layer permit stored for reconnect"
            );
        }
    }
}

