 76→fn issue_creator_layer_authority_permits(
 77→    state: &ScribeState,
 78→    full_layer_name: &str,
 79→    schema: &gurkha::DynamicLayerSchema,
 80→) {
 81→    let Some(ref issuer) = state.permit_issuer else { return; };
 82→
 83→    let mut targets: Vec<(String, Option<String>)> = Vec::new();
 84→    if let Ok(subs) = state.subscribers.read() {
 85→        for ((did, _device), info) in subs.iter() {
 86→            let role = info
 87→                .permit
 88→                .get_fact("role")
 89→                .and_then(|v| v.as_str())
 90→                .map(|r| r.to_string())
 91→                .or_else(|| {
 92→                    info.permit
 93→                        .get_fact("relationship")
 94→                        .and_then(|v| v.as_str())
 95→                        .map(|r| r.to_string())
 96→                });
 97→            targets.push((did.clone(), role));
 98→        }
 99→    }
100→
101→    for (audience, role) in targets {
102→        let Some(config) = authority_config_from_template(schema, role.as_deref()) else {
103→            warn!(
104→                page_id = %state.page_id,
105→                layer = %full_layer_name,
106→                audience = %audience,
107→                role = role.as_deref().unwrap_or("unknown"),
108→                "Skipping layer authority issuance: no matching template config"
109→            );
110→            continue;
111→        };
112→
113→        match issuer.issue_layer_authority_permit(
114→            &audience,
115→            full_layer_name,
116→            config,
117→            None,
118→            1,
119→        ) {
120→            Ok((_token, _cid)) => {
121→                info!(
122→                    page_id = %state.page_id,
123→                    layer = %full_layer_name,
124→                    audience = %audience,
125→                    "Issued creator layer authority permit"
126→                );
127→            }
128→            Err(e) => {
129→                warn!(
130→                    page_id = %state.page_id,
131→                    layer = %full_layer_name,
132→                    audience = %audience,
133→                    error = %e,
134→                    "Failed to issue creator layer authority permit"
135→                );
136→            }
137→        }
138→    }
139→}
