141→fn authority_config_from_template(
142→    schema: &gurkha::DynamicLayerSchema,
143→    role: Option<&str>,
144→) -> Option<gurkha::LayerConfig> {
145→    let mut config = match schema.grant {
146→        gurkha::GrantType::Explicit => schema.permissions.clone(),
147→        gurkha::GrantType::Role => role.and_then(|r| schema.role_permissions.get(r).cloned()),
148→    }?;
149→
150→    if config.layer_type.is_none() && !schema.layer_type.is_empty() {
151→        config.layer_type = Some(schema.layer_type.clone());
152→    }
153→
154→    Some(config)
155→}
