498→fn authority_layer_config_and_intent(
499→    issuer: &dyn PermitIssuer,
500→    audience_did: &str,
501→    layer_name: &str,
502→    page_id: &str,
503→) -> Option<(gurkha::LayerConfig, String)> {
504→    let (_version, authority_token) = issuer
505→        .get_layer_authority_permit(audience_did, layer_name)
506→        .ok()
507→        .flatten()?;
508→
509→    let parsed = gurkha::Permit::from_token(&authority_token).ok()?;
510→    let config = if let Some(c) = parsed.layers().get(layer_name) {
511→        c.clone()
512→    } else {
513→        let bare = crate::state::normalize_layer_name(layer_name, page_id);
514→        parsed.layers().get(&bare)?.clone()
515→    };
516→
517→    let intent_cid = gurkha::crypto::get_permit_cid(&authority_token).ok()?;
518→    Some((config, intent_cid))
519→}
