        let mut unit = LayerUnit::new_empty();
        unit.set_local_only(!state.should_sync_layer(layer_name));
        state.units.insert(layer_name.to_string(), unit);
        state.track_new_sync_layer_in_meta(layer_name);
        debug!(layer = %layer_name, "Created new layer");
    }

    // Auto-authorize target DID on __sync_meta/{did} layers so node-side
    // writes (e.g. fanout) can broadcast to the intended recipient.
    if let Some(target_did) = layer_name.strip_prefix("__sync_meta/") {
        if let Some(unit) = state.units.get(layer_name) {
            unit.authorize_did(target_did);
        }
    }

    is_new
}

