  1→//! 3-Step Sync Protocol
  2→//!
  3→//! Handles the SyncOffer → SyncAccept → SyncAck protocol for CRDT synchronization.
  4→//! Also includes asset sync triggering after layer sync completes.
  5→//!
  6→//! ## Bounded Resync Protocol
  7→//!
  8→//! When vectors diverge after SyncOffer/SyncAccept, we resync. But to prevent
  9→//! infinite loops, we track resync attempts:
 10→//!
 11→//! 1. `resync_attempts < MAX_RESYNC_ATTEMPTS`: Send another SyncOffer
 12→//! 2. `resync_attempts >= MAX_RESYNC_ATTEMPTS`: Send SyncReset (request full snapshot)
 13→//! 3. Node responds with SyncSnapshot (authoritative full state)
 14→//! 4. User replaces local layer entirely
 15→//!
 16→//! **Invariant**: Node is source of truth for divergence resolution.
 17→
 18→use tracing::{debug, error, info, trace, warn, instrument};
 19→use std::collections::BTreeSet;
 20→
 21→use crate::message::*;
 22→use transport::Connection;
 23→
 24→use super::super::guards::require_auth;
 25→use super::super::{PeerActor, PeerActorState, MAX_RESYNC_ATTEMPTS};
 26→
 27→impl<C: Connection> PeerActor<C> {
 28→
 29→    fn is_sync_meta_layer(page_id: &str, layer_name: &str) -> bool {
 30→        layer_name.starts_with("__sync_meta/")
 31→            || layer_name.starts_with(&format!("{}/__sync_meta/", page_id))
 32→    }
 33→
 34→    fn authority_schema_for_layer<'a>(
 35→        permit: &'a gurkha::Permit,
 36→        page_id: &str,
 37→        layer_name: &str,
 38→    ) -> Option<&'a gurkha::DynamicLayerSchema> {
 39→        let schemas = permit.dynamic_layer_schemas();
 40→        if schemas.is_empty() {
 41→            return None;
 42→        }
 43→
 44→        let bare_path = layer_name
 45→            .strip_prefix(&format!("{}/", page_id))
 46→            .unwrap_or(layer_name);
 47→        let path_parts: Vec<&str> = bare_path.split('/').collect();
 48→        if path_parts.len() < 3 || !path_parts[1].starts_with("did:") {
 49→            return None;
 50→        }
 51→
 52→        for (schema_key, schema) in schemas {
 53→            let pattern_parts: Vec<&str> = schema_key.split('/').collect();
 54→            if path_parts.len() != pattern_parts.len() + 1 {
 55→                continue;
 56→            }
 57→            if path_parts[0] != pattern_parts[0] {
 58→                continue;
 59→            }
 60→
 61→            let mut matched = true;
 62→            for (path_seg, pat_seg) in path_parts[2..].iter().zip(pattern_parts[1..].iter()) {
 63→                if *pat_seg != "{id}" && path_seg != pat_seg {
 64→                    matched = false;
 65→                    break;
 66→                }
 67→            }
 68→
 69→            if matched {
 70→                return Some(schema);
 71→            }
 72→        }
 73→
 74→        None
 75→    }
 76→
 77→    #[instrument(skip(self, authority_permit, scribe, state), fields(page_id = %page_id, layer = %layer_name))]
 78→    async fn fanout_sync_meta_from_authority(
 79→        &self,
 80→        page_id: &str,
 81→        layer_name: &str,
 82→        authority_permit: &gurkha::Permit,
 83→        scribe: &ractor::ActorRef<butler::ScribeMessage>,
 84→        state: &PeerActorState<C>,
 85→    ) {
 86→        let our_did = match state.butler.user_info().await {
 87→            Ok(info) => info.did,
 88→            Err(e) => {
 89→                warn!(error = %e, "Unable to resolve node DID for sync-meta fanout");
 90→                return;
 91→            }
 92→        };
 93→
 94→        let mut recipients = BTreeSet::new();
 95→        match authority_permit.authorized_peers() {
 96→            Ok(Some(explicit)) => {
 97→                for did in explicit {
 98→                    if did != our_did {
 99→                        recipients.insert(did);
100→                    }
101→                }
102→            }
103→            Ok(None) => {
104→                // Authority permit doesn't carry dynamic_layer_schemas — look up
105→                // the node's own page permit which has them.
106→                let our_page_permit = match state.butler.pages().get(page_id) {
107→                    Ok(Some(page)) => page.permit,
108→                    _ => None,
109→                };
110→                let parsed_page_permit = our_page_permit.as_deref().and_then(|t| gurkha::Permit::from_token(t).ok());
111→                let schema = parsed_page_permit.as_ref().and_then(|p| {
112→                    Self::authority_schema_for_layer(p, page_id, layer_name)
113→                });
114→                let Some(schema) = schema else {
115→                    warn!(page_id = %page_id, layer = %layer_name, "No matching dynamic schema in page permit for role fanout");
116→                    return;
117→                };
118→
119→                let all_users = match state.butler.store().list_authorized_users_for_page(page_id) {
120→                    Ok(users) => users,
121→                    Err(e) => {
122→                        warn!(error = %e, "Failed to list authorized users for role fanout");
123→                        return;
124→                    }
125→                };
126→
127→                for user_did in all_users {
128→                    if user_did == our_did {
129→                        continue;
130→                    }
131→
132→                    let permit_token = match state.butler.store().get_user_page_permit(page_id, &user_did) {
133→                        Ok(Some(p)) => p,
134→                        _ => continue,
135→                    };
136→
137→                    let parsed = match gurkha::Permit::from_token(&permit_token) {
138→                        Ok(p) => p,
139→                        Err(_) => continue,
140→                    };
141→
142→                    let role = parsed
143→                        .get_fact("role")
144→                        .and_then(|v| v.as_str())
145→                        .or_else(|| parsed.get_fact("relationship").and_then(|v| v.as_str()));
146→
147→                    if let Some(role) = role {
148→                        if schema.role_permissions.contains_key(role) {
149→                            recipients.insert(user_did);
150→                        }
151→                    }
152→                }
153→            }
154→            Err(e) => {
155→                warn!(error = %e, "Invalid authorized_peers in layer authority permit");
156→                return;
157→            }
158→        }
159→
160→        info!(page_id = %page_id, layer = %layer_name, count = recipients.len(), "Fanout sync-meta to recipients");
161→
162→        for did in recipients {
163→            let sync_meta_layer = format!("__sync_meta/{}", did);
164→            let sync_meta_key = layer_name
165→                .strip_prefix(&format!("{}/", page_id))
166→                .unwrap_or(layer_name)
167→                .to_string();
168→            info!(page_id = %page_id, target = %did, sync_meta_layer = %sync_meta_layer, key = %sync_meta_key, "Writing sync-meta entry for recipient");
169→            if let Err(e) = scribe.cast(butler::ScribeMessage::MapInsert {
170→                layer_name: sync_meta_layer,
171→                path: String::new(),
172→                key: sync_meta_key,
173→                value: serde_json::json!({"synced": false, "version": 1}),
174→            }) {
175→                warn!(page_id = %page_id, layer = %layer_name, target = %did, error = %e, "Failed to write recipient sync-meta entry");
176→            }
177→        }
178→    }
179→
180→    #[instrument(skip(self, state, scribe), fields(page_id = %page_id, sync_meta_layer = %sync_meta_layer))]
181→    async fn request_missing_layers_from_sync_meta(
182→        &self,
183→        page_id: &str,
184→        sync_meta_layer: &str,
185→        scribe: &ractor::ActorRef<butler::ScribeMessage>,
186→        state: &mut PeerActorState<C>,
187→    ) {
188→        let normalized_sync_meta_layer = sync_meta_layer
189→            .strip_prefix(&format!("{}/", page_id))
190→            .unwrap_or(sync_meta_layer)
191→            .to_string();
192→
193→        let (data_tx, data_rx) = tokio::sync::oneshot::channel();
194→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetLayerData {
195→            layer_name: normalized_sync_meta_layer,
196→            reply: data_tx,
197→        }) {
198→            warn!(error = %e, "Failed to read sync-meta layer for request planning");
199→            return;
200→        }
201→
202→        let sync_meta_json = match data_rx.await {
203→            Ok(Ok(v)) => v,
204→            Ok(Err(e)) => {
205→                warn!(error = %e, "GetLayerData failed for sync-meta layer");
206→                return;
207→            }
208→            Err(_) => {
209→                warn!("GetLayerData reply channel closed for sync-meta layer");
210→                return;
211→            }
212→        };
213→
214→        let Some(entries) = sync_meta_json.as_object() else {
215→            warn!("sync-meta layer content is not a map object");
216→            return;
217→        };
218→
219→        for (layer_name, entry) in entries {
220→            let normalized_layer_name = layer_name
221→                .strip_prefix(&format!("{}/", page_id))
222→                .unwrap_or(layer_name)
223→                .to_string();
224→
225→            if normalized_layer_name.starts_with("__sync_meta/") {
226→                continue;
227→            }
228→
229→            let should_request = entry
230→                .get("synced")
231→                .and_then(serde_json::Value::as_bool)
232→                .map(|s| !s)
233→                .unwrap_or(true);
234→            if !should_request {
235→                continue;
236→            }
237→
238→            let (exists_tx, exists_rx) = tokio::sync::oneshot::channel();
239→            if let Err(e) = scribe.cast(butler::ScribeMessage::LayerExists {
240→                layer_name: normalized_layer_name.clone(),
241→                reply: exists_tx,
242→            }) {
243→                warn!(layer = %normalized_layer_name, error = %e, "Failed to check layer existence");
244→                continue;
245→            }
246→
247→            let exists = match exists_rx.await {
248→                Ok(v) => v,
249→                Err(_) => {
250→                    warn!(layer = %normalized_layer_name, "LayerExists reply channel closed");
251→                    continue;
252→                }
253→            };
254→
255→            if exists {
256→                continue;
257→            }
258→
259→            info!(page_id = %page_id, layer = %normalized_layer_name, "Requesting missing layer via SyncReset after sync-meta discovery");
260→            let msg = Message::SyncReset(SyncResetMsg {
261→                page_id: page_id.to_string(),
262→                layer_name: normalized_layer_name,
263→            });
264→            self.send_message(&msg, state).await;
265→        }
266→    }
267→
268→    /// Handle incoming SyncOffer from peer (Step 1)
269→    ///
270→    /// **Context**: Peer has a layer update with their state vector
271→    /// **Peer sends**: SyncOffer with page_id, layer_name, encrypted data, state_vector
272→    /// **We decrypt**: ECDH with ephemeral_public + our encryption key
273→    /// **We apply**: Via Scribe.ApplyUpdateWithResult (handles merge)
274→    /// **We respond**: SyncAccept with our state vector after applying (only if successful)
275→    #[instrument(skip(self, myself, state, data, their_state_vector, ephemeral_public), fields(page_id = %page_id, layer_name = %layer_name))]
276→    pub(in crate::peer_actor) async fn on_sync_offer(
277→        &self,
278→        myself: ractor::ActorRef<super::super::PeerMessage>,
279→        page_id: &str,
280→        layer_name: &str,
281→        data: &[u8],
282→        their_state_vector: &[u8],
283→        ephemeral_public: &[u8; 32],
284→        authority_permit: Option<&str>,
285→        state: &mut PeerActorState<C>,
286→    ) {
287→        let (peer_did, _) = match require_auth(&state.state) {
288→            Ok(info) => (info.0.to_string(), info.1.to_string()),
289→            Err(_) => {
290→                warn!("SyncOffer from unauthenticated peer: {}", self.node_id);
291→                return;
292→            }
293→        };
294→
295→        let peer_device_id = self.node_id.to_string();
296→
297→        debug!(
298→            "SyncOffer: page={} layer={} ({} bytes, vector {} bytes) from {}",
299→            page_id, layer_name, data.len(), their_state_vector.len(), peer_did
300→        );
301→
302→        // Open page early so bundled authority fanout and apply share one Scribe handle.
303→        let scribe = match state.butler.open_page(page_id).await {
304→            Ok(s) => s,
305→            Err(e) => {
306→                error!("Failed to open page {}: {}", page_id, e);
307→                return;
308→            }
309→        };
310→
311→        if let Some(permit) = authority_permit {
312→            match gurkha::Permit::from_token(permit) {
313→                Ok(parsed) => {
314→                    if parsed.token_type() == Some("layer_authority") {
315→                        let audience = parsed.parsed().audience().to_string();
316→                        let version = parsed
317→                            .get_fact("version")
318→                            .and_then(|v| v.as_u64())
319→                            .unwrap_or(0);
320→                        let full_layer_name = if layer_name.starts_with(&format!("{}/", page_id)) {
321→                            layer_name.to_string()
322→                        } else {
323→                            format!("{}/{}", page_id, layer_name)
324→                        };
325→                        if let Err(e) = state.butler.permits().store_layer_authority_permit(
326→                            page_id,
327→                            &full_layer_name,
328→                            &audience,
329→                            version,
330→                            permit,
331→                        ) {
332→                            warn!(
333→                                page_id = %page_id,
334→                                layer = %full_layer_name,
335→                                audience = %audience,
336→                                error = %e,
337→                                "Failed to store bundled layer authority permit"
338→                            );
339→                        }
340→
341→                        if state.mode == crate::CourierMode::Node {
342→                            self
343→                                .fanout_sync_meta_from_authority(
344→                                    page_id,
345→                                    &full_layer_name,
346→                                    &parsed,
347→                                    &scribe,
348→                                    state,
349→                                )
350→                                .await;
351→                        }
352→                    }
353→                }
354→                Err(e) => {
355→                    warn!(page_id = %page_id, layer = %layer_name, error = %e, "Invalid bundled authority permit in SyncOffer");
356→                }
357→            }
358→        }
359→
360→        // Decrypt transit-encrypted update using ECDH
361→        let our_secret = match state.butler.encryption_key().await {
362→            Ok(key) => key,
363→            Err(e) => {
364→                error!("Failed to get encryption key for SyncOffer decryption: {}", e);
365→                return;
366→            }
367→        };
368→        let decrypted_data = match herald::decrypt_from_transfer(&our_secret, ephemeral_public, data) {
369→            Ok(data) => data,
370→            Err(e) => {
371→                error!("Failed to decrypt SyncOffer from {}: {}", peer_did, e);
372→                return;
373→            }
374→        };
375→
376→        // Auto-subscribe peer if not already subscribed (both Node and User modes)
377→        // For Node mode: Ensures can_write() can check viewer's write permissions
378→        // For User mode: Ensures node gets subscribed to viewer's scribe for bidirectional sync
379→        if !state.page_subscriptions.contains_key(page_id) {
380→            info!("Auto-subscribing peer {} to page {} from SyncOffer", peer_did, page_id);
381→            self.subscribe_to_page(myself.clone(), page_id, "", state).await;
382→        }
383→
384→        // Apply the update with result feedback
385→        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
386→        if let Err(e) = scribe.cast(butler::ScribeMessage::ApplyUpdateWithResult {
387→            layer_name: layer_name.to_string(),
388→            update: decrypted_data,
389→            from_peer: Some((peer_did.clone(), peer_device_id.clone())),
390→            permit: None,
391→            reply: reply_tx,
392→        }) {
393→            error!("Failed to send ApplyUpdateWithResult to Scribe: {}", e);
394→            return;
395→        }
396→
397→        // Wait for apply result - only send SyncAccept if successful
398→        match reply_rx.await {
399→            Ok(Ok(())) => {
400→                debug!("ApplyUpdate succeeded for page={} layer={}", page_id, layer_name);
401→
402→                if Self::is_sync_meta_layer(page_id, layer_name) {
403→                    self
404→                        .request_missing_layers_from_sync_meta(page_id, layer_name, &scribe, state)
405→                        .await;
406→                }
407→            }
408→            Ok(Err(e)) => {
409→                warn!("ApplyUpdate rejected for page={} layer={}: {}", page_id, layer_name, e);
410→                // DO NOT send SyncAccept - this stops the infinite retry loop
411→                return;
412→            }
413→            Err(_) => {
414→                error!("ApplyUpdate reply channel closed for page={} layer={}", page_id, layer_name);
415→                return;
416→            }
417→        }
418→
419→        // Get our state vector after applying
420→        let (tx, rx) = tokio::sync::oneshot::channel();
421→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetStateVector {
422→            layer_name: layer_name.to_string(),
423→            reply: tx.into(),
424→        }) {
425→            error!("Failed to request state vector from Scribe: {}", e);
426→            return;
427→        }
428→
429→        let our_state_vector = match rx.await {
430→            Ok(Ok(vector)) => vector,
431→            Ok(Err(e)) => {
432→                error!("Scribe returned error getting state vector: {}", e);
433→                return;
434→            }
435→            Err(_) => {
436→                error!("Scribe dropped state vector reply channel");
437→                return;
438→            }
439→        };
440→
441→        // Send SyncAccept with our state vector
442→        let msg = Message::SyncAccept(SyncAcceptMsg {
443→            page_id: page_id.to_string(),
444→            layer_name: layer_name.to_string(),
445→            state_vector: our_state_vector.clone(),
446→        });
447→
448→        self.send_message(&msg, state).await;
449→        debug!(
450→            "Sent SyncAccept for page={} layer={} to {} (our vector {} bytes)",
451→            page_id, layer_name, peer_did, our_state_vector.len()
452→        );
453→    }
454→
455→    /// Handle incoming SyncAccept from peer (Step 2)
456→    ///
457→    /// **Context**: Peer applied our update and reports their state vector
458→    /// **Peer sends**: SyncAccept with their state vector after applying
459→    /// **We compare**: Their vector with our current vector
460→    /// **If match**: Send SyncAck (sync complete)
461→    /// **If diverged**: Send new SyncOffer with full diff from their vector (resync)
462→    #[instrument(skip(self, state, their_state_vector), fields(page_id = %page_id, layer_name = %layer_name))]
463→    pub(in crate::peer_actor) async fn on_sync_accept(
464→        &self,
465→        page_id: &str,
466→        layer_name: &str,
467→        their_state_vector: &[u8],
468→        state: &mut PeerActorState<C>,
469→    ) {
470→        let (peer_did, _) = match require_auth(&state.state) {
471→            Ok(info) => (info.0.to_string(), info.1.to_string()),
472→            Err(_) => {
473→                warn!("SyncAccept from unauthenticated peer: {}", self.node_id);
474→                return;
475→            }
476→        };
477→
478→        debug!(
479→            "SyncAccept: page={} layer={} from {} (their vector {} bytes)",
480→            page_id, layer_name, peer_did, their_state_vector.len()
481→        );
482→
483→        // Get pending sync context (may not exist for fire-and-forget broadcasts)
484→        let key = (page_id.to_string(), layer_name.to_string());
485→        let pending = state.pending_sync_offers.remove(&key);
486→
487→        // Get our current state vector from Scribe
488→        let scribe = match state.butler.open_page(page_id).await {
489→            Ok(s) => s,
490→            Err(e) => {
491→                error!("Failed to open page {}: {}", page_id, e);
492→                return;
493→            }
494→        };
495→
496→        let (tx, rx) = tokio::sync::oneshot::channel();
497→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetStateVector {
498→            layer_name: layer_name.to_string(),
499→            reply: tx.into(),
500→        }) {
501→            error!("Failed to request state vector from Scribe: {}", e);
502→            return;
503→        }
504→
505→        let our_current_vector = match rx.await {
506→            Ok(Ok(vector)) => vector,
507→            Ok(Err(e)) => {
508→                error!("Scribe returned error getting state vector: {}", e);
509→                return;
510→            }
511→            Err(_) => {
512→                error!("Scribe dropped state vector reply channel");
513→                return;
514→            }
515→        };
516→
517→        // Handle based on whether we have a pending offer
518→        match pending {
519→            None => {
520→                // Fire-and-forget broadcast: No pending offer tracked.
521→                // Just update peer vector cache and send SyncAck. Trust CRDT to converge.
522→                debug!(
523→                    "SyncAccept: no pending offer (fire-and-forget) for page={} layer={} - sending SyncAck",
524→                    page_id, layer_name
525→                );
526→
527→                let msg = Message::SyncAck(SyncAckMsg {
528→                    page_id: page_id.to_string(),
529→                    layer_name: layer_name.to_string(),
530→                    state_vector: our_current_vector,
531→                });
532→                self.send_message(&msg, state).await;
533→
534→                // Update Scribe's in-memory vector cache (persistence via periodic flush)
535→                let peer_device_id = self.node_id.to_string();
536→                if let Some(subscription) = state.page_subscriptions.get(page_id) {
537→                    let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
538→                        user_did: peer_did,
539→                        device_id: peer_device_id,
540→                        layer_name: layer_name.to_string(),
541→                        state_vector: their_state_vector.to_vec(),
542→                    });
543→                }
544→            }
545→            Some(offer) => {
546→                // Tracked sync (initial sync / reconciliation): Compare vectors
547→                trace!(
548→                    "SyncAccept comparison: their_vector={} bytes, offered_vector={} bytes, current_vector={} bytes",
549→                    their_state_vector.len(),
550→                    offer.our_state_vector.len(),
551→                    our_current_vector.len()
552→                );
553→
554→                if their_state_vector == offer.our_state_vector.as_slice() {
555→                    // In sync! Send SyncAck
556→                    trace!(
557→                        "SyncAccept: vectors match for page={} layer={} - sending SyncAck",
558→                        page_id, layer_name
559→                    );
560→
561→                    let msg = Message::SyncAck(SyncAckMsg {
562→                        page_id: page_id.to_string(),
563→                        layer_name: layer_name.to_string(),
564→                        state_vector: our_current_vector,
565→                    });
566→                    self.send_message(&msg, state).await;
567→
568→                    // Update Scribe's in-memory vector cache (persistence via periodic flush)
569→                    let peer_device_id = self.node_id.to_string();
570→                    if let Some(subscription) = state.page_subscriptions.get(page_id) {
571→                        let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
572→                            user_did: peer_did,
573→                            device_id: peer_device_id,
574→                            layer_name: layer_name.to_string(),
575→                            state_vector: their_state_vector.to_vec(),
576→                        });
577→                    }
578→                } else {
579→                    // Diverged! Check if we should resync or fall back to SyncReset
580→                    let new_attempts = offer.resync_attempts + 1;
581→
582→                    if new_attempts > MAX_RESYNC_ATTEMPTS {
583→                        // Max resyncs exceeded - fall back to SyncReset (request full snapshot)
584→                        warn!(
585→                            "SyncAccept: max resyncs ({}) exceeded for page={} layer={} - sending SyncReset",
586→                            MAX_RESYNC_ATTEMPTS, page_id, layer_name
587→                        );
588→
589→                        let msg = Message::SyncReset(SyncResetMsg {
590→                            page_id: page_id.to_string(),
591→                            layer_name: layer_name.to_string(),
592→                        });
593→                        self.send_message(&msg, state).await;
594→                        return;
595→                    }
596→
597→                    // Still have retries - send resync SyncOffer with full diff from their vector
598→                    info!(
599→                        "SyncAccept: vectors DIVERGED for page={} layer={} - sending resync SyncOffer (attempt {}/{})",
600→                        page_id, layer_name, new_attempts, MAX_RESYNC_ATTEMPTS
601→                    );
602→
603→                    // Get diff from their state vector
604→                    let (tx, rx) = tokio::sync::oneshot::channel();
605→                    if let Err(e) = scribe.cast(butler::ScribeMessage::GetUpdatesSince {
606→                        layer_name: layer_name.to_string(),
607→                        state_vector: their_state_vector.to_vec(),
608→                        reply: tx,
609→                    }) {
610→                        error!("Failed to request updates from Scribe: {}", e);
611→                        return;
612→                    }
613→
614→                    let diff = match rx.await {
615→                        Ok(Ok(d)) => d,
616→                        Ok(Err(e)) => {
617→                            error!("Scribe returned error getting updates: {}", e);
618→                            return;
619→                        }
620→                        Err(_) => {
621→                            error!("Scribe dropped updates reply channel");
622→                            return;
623→                        }
624→                    };
625→
626→                    // Encrypt and send new SyncOffer
627→                    let peer_encryption_key = match state.peer_encryption_key {
628→                        Some(key) => key,
629→                        None => {
630→                            warn!("Cannot send resync SyncOffer: peer encryption key not set");
631→                            return;
632→                        }
633→                    };
634→
635→                    let (ephemeral_public, encrypted_data) = match herald::encrypt_for_transfer(
636→                        &peer_encryption_key,
637→                        &diff,
638→                    ) {
639→                        Ok(result) => result,
640→                        Err(e) => {
641→                            error!("Failed to encrypt resync data: {}", e);
642→                            return;
643→                        }
644→                    };
645→
646→                    // Track this new pending sync with incremented attempt counter
647→                    state.pending_sync_offers.insert(
648→                        key,
649→                        super::super::PendingSyncOffer {
650→                            our_state_vector: our_current_vector.clone(),
651→                            permit: String::new(),
652→                            resync_attempts: new_attempts,
653→                        },
654→                    );
655→
656→                    let layer_name_owned = layer_name.to_string();
657→                    let msg = Message::SyncOffer(SyncOfferMsg {
658→                        page_id: page_id.to_string(),
659→                        layer_type: LayerType::from_layer_name(&layer_name_owned),
660→                        layer_name: layer_name_owned,
661→                        data: encrypted_data,
662→                        state_vector: our_current_vector,
663→                        ephemeral_public,
664→                        authority_permit: None,
665→                    });
666→                    self.send_message(&msg, state).await;
667→                }
668→            }
669→        }
670→    }
671→
672→    /// Handle incoming SyncAck from peer (Step 3)
673→    ///
674→    /// **Context**: Peer confirms sync complete after comparing vectors
675→    /// **Peer sends**: SyncAck with their final state vector
676→    /// **We do**: Update cached peer vector, log sync complete
677→    #[instrument(skip(self, state, their_state_vector), fields(page_id = %page_id, layer_name = %layer_name))]
678→    pub(in crate::peer_actor) async fn on_sync_ack(
679→        &self,
680→        page_id: &str,
681→        layer_name: &str,
682→        their_state_vector: &[u8],
683→        state: &mut PeerActorState<C>,
684→    ) {
685→        let (peer_did, _) = match require_auth(&state.state) {
686→            Ok(info) => (info.0.to_string(), info.1.to_string()),
687→            Err(_) => {
688→                warn!("SyncAck from unauthenticated peer: {}", self.node_id);
689→                return;
690→            }
691→        };
692→
693→        debug!(
694→            "SyncAck: page={} layer={} from {} - sync complete",
695→            page_id, layer_name, peer_did
696→        );
697→
698→        // Update Scribe's in-memory vector cache (persistence via periodic flush)
699→        let peer_device_id = self.node_id.to_string();
700→        if let Some(subscription) = state.page_subscriptions.get(page_id) {
701→            let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
702→                user_did: peer_did.clone(),
703→                device_id: peer_device_id.clone(),
704→                layer_name: layer_name.to_string(),
705→                state_vector: their_state_vector.to_vec(),
706→            });
707→
708→            if !Self::is_sync_meta_layer(page_id, layer_name) {
709→                if let Ok(user_info) = state.butler.user_info().await {
710→                    let sync_meta_layer = format!("__sync_meta/{}", user_info.did);
711→                    let sync_meta_key = layer_name
712→                        .strip_prefix(&format!("{}/", page_id))
713→                        .unwrap_or(layer_name)
714→                        .to_string();
715→                    let _ = subscription.scribe.cast(butler::ScribeMessage::MapInsert {
716→                        layer_name: sync_meta_layer,
717→                        path: String::new(),
718→                        key: sync_meta_key,
719→                        value: serde_json::json!({"synced": true, "version": 1}),
720→                    });
721→                }
722→            }
723→        }
724→
725→        // Clean up any pending sync for this page/layer (shouldn't exist but be safe)
726→        let key = (page_id.to_string(), layer_name.to_string());
727→        state.pending_sync_offers.remove(&key);
728→
729→        // Check if this is an assets layer sync - trigger asset fetch for missing blobs
730→        if layer_name == "assets" || layer_name.ends_with("/assets") {
731→            self.trigger_asset_sync_after_layer_sync(page_id, layer_name, state).await;
732→        }
733→    }
734→
735→    /// Handle incoming SyncReset from peer (fallback after max resyncs)
736→    ///
737→    /// **Context**: Peer exceeded MAX_RESYNC_ATTEMPTS OR explicitly needs layer snapshot.
738→    /// **Both modes**: Respond with SyncSnapshot when layer exists locally.
739→    #[instrument(skip(self, state), fields(page_id = %page_id, layer_name = %layer_name))]
740→    pub(in crate::peer_actor) async fn on_sync_reset(
741→        &self,
742→        page_id: &str,
743→        layer_name: &str,
744→        state: &mut PeerActorState<C>,
745→    ) {
746→        let peer_did = match require_auth(&state.state) {
747→            Ok((did, _)) => did.to_string(),
748→            Err(_) => {
749→                warn!("SyncReset from unauthenticated peer: {}", self.node_id);
750→                return;
751→            }
752→        };
753→
754→        info!(
755→            "SyncReset: page={} layer={} from {} - sending full snapshot",
756→            page_id, layer_name, peer_did
757→        );
758→
759→        // Get Scribe and export full snapshot
760→        let scribe = match state.butler.open_page(page_id).await {
761→            Ok(s) => s,
762→            Err(e) => {
763→                error!("Failed to open page {} for SyncReset: {}", page_id, e);
764→                return;
765→            }
766→        };
767→
768→        // Get full snapshot
769→        let (snapshot_tx, snapshot_rx) = tokio::sync::oneshot::channel();
770→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetSnapshot {
771→            layer_name: layer_name.to_string(),
772→            reply: snapshot_tx,
773→        }) {
774→            error!("Failed to request snapshot from Scribe: {}", e);
775→            return;
776→        }
777→
778→        let snapshot = match snapshot_rx.await {
779→            Ok(Some(data)) => data,
780→            Ok(None) => {
781→                warn!("Layer {} not found in Scribe for SyncReset", layer_name);
782→                return;
783→            }
784→            Err(_) => {
785→                error!("Scribe dropped snapshot reply channel");
786→                return;
787→            }
788→        };
789→
790→        // Get state vector
791→        let (vector_tx, vector_rx) = tokio::sync::oneshot::channel();
792→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetStateVector {
793→            layer_name: layer_name.to_string(),
794→            reply: vector_tx.into(),
795→        }) {
796→            error!("Failed to request state vector from Scribe: {}", e);
797→            return;
798→        }
799→
800→        let state_vector = match vector_rx.await {
801→            Ok(Ok(v)) => v,
802→            Ok(Err(e)) => {
803→                error!("Scribe returned error getting state vector: {}", e);
804→                return;
805→            }
806→            Err(_) => {
807→                error!("Scribe dropped state vector reply channel");
808→                return;
809→            }
810→        };
811→
812→        // Encrypt snapshot for transfer
813→        let peer_encryption_key = match state.peer_encryption_key {
814→            Some(key) => key,
815→            None => {
816→                warn!("Cannot send SyncSnapshot: peer encryption key not set");
817→                return;
818→            }
819→        };
820→
821→        let (ephemeral_public, encrypted_snapshot) = match herald::encrypt_for_transfer(
822→            &peer_encryption_key,
823→            &snapshot,
824→        ) {
825→            Ok(result) => result,
826→            Err(e) => {
827→                error!("Failed to encrypt snapshot: {}", e);
828→                return;
829→            }
830→        };
831→
832→        // Send SyncSnapshot
833→        let layer_name_owned = layer_name.to_string();
834→        let msg = Message::SyncSnapshot(SyncSnapshotMsg {
835→            page_id: page_id.to_string(),
836→            layer_type: LayerType::from_layer_name(&layer_name_owned),
837→            layer_name: layer_name_owned,
838→            snapshot: encrypted_snapshot,
839→            state_vector,
840→            ephemeral_public,
841→        });
842→        self.send_message(&msg, state).await;
843→
844→        info!(
845→            "Sent SyncSnapshot for page={} layer={} to {} ({} bytes)",
846→            page_id, layer_name, peer_did, snapshot.len()
847→        );
848→    }
849→
850→    /// Handle incoming SyncSnapshot from peer (response to SyncReset)
851→    ///
852→    /// **Context**: Peer responded to our SyncReset with a full snapshot.
853→    /// **Both modes**: Replace local layer with received state.
854→    #[instrument(skip(self, state, snapshot, their_state_vector, ephemeral_public), fields(page_id = %page_id, layer_name = %layer_name))]
855→    pub(in crate::peer_actor) async fn on_sync_snapshot(
856→        &self,
857→        page_id: &str,
858→        layer_name: &str,
859→        snapshot: &[u8],
860→        their_state_vector: &[u8],
861→        ephemeral_public: &[u8; 32],
862→        state: &mut PeerActorState<C>,
863→    ) {
864→        let peer_did = match require_auth(&state.state) {
865→            Ok((did, _)) => did.to_string(),
866→            Err(_) => {
867→                warn!("SyncSnapshot from unauthenticated peer: {}", self.node_id);
868→                return;
869→            }
870→        };
871→
872→        info!(
873→            "SyncSnapshot: page={} layer={} from {} ({} bytes) - replacing local state",
874→            page_id, layer_name, peer_did, snapshot.len()
875→        );
876→
877→        // Decrypt snapshot
878→        let our_secret = match state.butler.encryption_key().await {
879→            Ok(key) => key,
880→            Err(e) => {
881→                error!("Failed to get encryption key for SyncSnapshot decryption: {}", e);
882→                return;
883→            }
884→        };
885→
886→        let decrypted_snapshot = match herald::decrypt_from_transfer(&our_secret, ephemeral_public, snapshot) {
887→            Ok(data) => data,
888→            Err(e) => {
889→                error!("Failed to decrypt SyncSnapshot from {}: {}", peer_did, e);
890→                return;
891→            }
892→        };
893→
894→        // Get Scribe and replace layer
895→        let scribe = match state.butler.open_page(page_id).await {
896→            Ok(s) => s,
897→            Err(e) => {
898→                error!("Failed to open page {} for SyncSnapshot: {}", page_id, e);
899→                return;
900→            }
901→        };
902→
903→        // Replace layer with snapshot
904→        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
905→        if let Err(e) = scribe.cast(butler::ScribeMessage::ReplaceLayer {
906→            layer_name: layer_name.to_string(),
907→            snapshot: decrypted_snapshot,
908→            reply: reply_tx,
909→        }) {
910→            error!("Failed to send ReplaceLayer to Scribe: {}", e);
911→            return;
912→        }
913→
914→        match reply_rx.await {
915→            Ok(Ok(())) => {
916→                info!(
917→                    "SyncSnapshot applied: page={} layer={} - sync recovery complete",
918→                    page_id, layer_name
919→                );
920→
921→                if Self::is_sync_meta_layer(page_id, layer_name) {
922→                    self
923→                        .request_missing_layers_from_sync_meta(page_id, layer_name, &scribe, state)
924→                        .await;
925→                }
926→            }
927→            Ok(Err(e)) => {
928→                error!("ReplaceLayer failed for page={} layer={}: {}", page_id, layer_name, e);
929→                return;
930→            }
931→            Err(_) => {
932→                error!("Scribe dropped ReplaceLayer reply channel");
933→                return;
934→            }
935→        }
936→
937→        // Update Scribe's in-memory vector cache (persistence via periodic flush)
938→        let peer_device_id = self.node_id.to_string();
939→        if let Some(subscription) = state.page_subscriptions.get(page_id) {
940→            let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
941→                user_did: peer_did.clone(),
942→                device_id: peer_device_id,
943→                layer_name: layer_name.to_string(),
944→                state_vector: their_state_vector.to_vec(),
945→            });
946→
947→            if !Self::is_sync_meta_layer(page_id, layer_name) {
948→                if let Ok(user_info) = state.butler.user_info().await {
949→                    let sync_meta_layer = format!("__sync_meta/{}", user_info.did);
950→                    let sync_meta_key = layer_name
951→                        .strip_prefix(&format!("{}/", page_id))
952→                        .unwrap_or(layer_name)
953→                        .to_string();
954→                    let _ = subscription.scribe.cast(butler::ScribeMessage::MapInsert {
955→                        layer_name: sync_meta_layer,
956→                        path: String::new(),
957→                        key: sync_meta_key,
958→                        value: serde_json::json!({"synced": true, "version": 1}),
959→                    });
960→                }
961→            }
962→        }
963→
964→        // Clean up any pending sync
965→        let key = (page_id.to_string(), layer_name.to_string());
966→        state.pending_sync_offers.remove(&key);
967→    }
968→}
