1543→    let owner_page_permit = owner_page
1544→        .permit
1545→        .clone()
1546→        .expect("owner page should have permit");
1547→
1548→    for did in &audience_dids {
1549→        let (authority_token, _) = gurkha::issue_layer_permit(
