  1→//! Peer — single participant using MockConnection only
  2→//!
  3→//! No generics, no IrohConnection support. Fast, in-memory protocol testing.
  4→
  5→use std::sync::Arc;
  6→use std::time::Duration;
  7→
  8→use anyhow::Result;
  9→use tokio::sync::{mpsc, RwLock};
 10→use tracing::info;
 11→use transport::{MockBlobStore, MockConnection, NodeId, mock_connection_pair, node_id_from_secret};
 12→
 13→use butler::{Butler, LayerCache, RedbStore, signup};
 14→use courier::coordinator::{Coordinator, CoordinatorMessage, CourierMode};
 15→use courier::peer_actor::BlobStore;
 16→use courier::trace::MessageTrace;
 17→use courier::CourierEvent;
 18→use ractor::{Actor, ActorRef};
 19→
 20→/// Mock-only test peer
 21→pub struct Peer {
 22→    pub name: String,
 23→    pub node_id: NodeId,
 24→    pub mode: CourierMode,
 25→    pub coordinator: ActorRef<CoordinatorMessage<MockConnection>>,
 26→    pub butler: Arc<Butler>,
 27→    pub events: mpsc::Receiver<CourierEvent>,
 28→    _temp_dir: tempfile::TempDir,
 29→}
 30→
 31→impl Peer {
 32→    /// Create a new mock peer
 33→    ///
 34→    /// Pass `message_tx` from `Tracer::new()` to enable protocol tracing,
 35→    /// or `None` for tests that don't need it.
 36→    pub async fn new(
 37→        name: &str,
 38→        mode: CourierMode,
 39→        blobs: Arc<MockBlobStore>,
 40→        message_tx: Option<mpsc::UnboundedSender<MessageTrace>>,
 41→    ) -> Result<Self> {
 42→        let temp_dir = tempfile::tempdir()?;
 43→        let db_path = temp_dir.path().join(format!("{}.redb", name));
 44→
 45→        // Storage
 46→        let store = Arc::new(RedbStore::open(&db_path)?);
 47→        let layer_cache = Arc::new(RwLock::new(LayerCache::new(store.clone(), 100)));
 48→        let assets_path = temp_dir.path().join("assets");
 49→        let asset_store = Arc::new(butler::AssetStore::new(&assets_path)?);
 50→
 51→        // Wire sync_event channel so Scribe -> EnsureSync -> Coordinator works
 52→        let (sync_tx, mut sync_rx) = mpsc::channel::<butler::SyncEvent>(100);
 53→        let butler = Arc::new(Butler::new(store.clone(), layer_cache, asset_store, Some(sync_tx)));
 54→
 55→        // Create identity
 56→        let signup_result = signup(&store, name, "password")?;
 57→        butler.set_identity(signup_result.identity).await;
 58→
 59→        // Derive node_id from device key
 60→        let device_key = butler.device_key().await?;
 61→        let node_id = node_id_from_secret(&device_key);
 62→
 63→        // Event channel
 64→        let (event_tx, event_rx) = mpsc::channel::<CourierEvent>(100);
 65→
 66→        // Connect request channel (unused for mock — we inject connections directly)
 67→        let (connect_tx, _connect_rx) = mpsc::channel::<courier::ConnectRequest>(16);
 68→
 69→        // Coordinator
 70→        let blob = BlobStore::Mock(blobs);
 71→        let (coordinator, _) = Actor::spawn(
 72→            Some(format!("coordinator-{}-{}", name, node_id)),
 73→            Coordinator::<MockConnection>::new(),
 74→            (node_id, mode, butler.clone(), blob, Some(connect_tx), Some(event_tx), message_tx, None),
 75→        )
 76→        .await?;
 77→
 78→        // Forward EnsureSync from Scribe to Coordinator
 79→        let coord = coordinator.clone();
 80→        tokio::spawn(async move {
 81→            while let Some(event) = sync_rx.recv().await {
 82→                match event {
 83→                    butler::SyncEvent::EnsureSync { user_did } => {
 84→                        let _ = coord.cast(CoordinatorMessage::EnsureSync { user_did });
 85→                    }
 86→                    butler::SyncEvent::NewDynamicLayer { page_id, layer_name, permits } => {
 87→                        let _ = coord.cast(CoordinatorMessage::DistributeLayerPermits {
 88→                            page_id, layer_name, permits,
 89→                        });
 90→                    }
 91→                    butler::SyncEvent::LayerAccessChanged { page_id, layer_name, permits } => {
 92→                        let _ = coord.cast(CoordinatorMessage::DistributeLayerPermits {
 93→                            page_id, layer_name, permits,
 94→                        });
 95→                    }
 96→                }
 97→            }
 98→        });
 99→
100→        info!("Peer '{}' created: node_id={}, mode={:?}", name, node_id, mode);
101→
102→        Ok(Self {
103→            name: name.to_string(),
104→            node_id,
105→            mode,
106→            coordinator,
107→            butler,
108→            events: event_rx,
109→            _temp_dir: temp_dir,
110→        })
111→    }
112→
113→    /// Connect to another mock peer using in-memory channels
114→    pub fn connect_to(&self, other: &Peer) -> Result<()> {
115→        let (conn_to_other, conn_to_self) = mock_connection_pair(self.node_id, other.node_id);
116→
117→        self.coordinator
118→            .cast(CoordinatorMessage::Connected {
119→                node_id: other.node_id,
120→                conn: conn_to_other,
121→            })
122→            .map_err(|e| anyhow::anyhow!("Failed to inject connection: {:?}", e))?;
123→
124→        other
125→            .coordinator
126→            .cast(CoordinatorMessage::Connected {
127→                node_id: self.node_id,
128→                conn: conn_to_self,
129→            })
130→            .map_err(|e| anyhow::anyhow!("Failed to inject connection: {:?}", e))?;
131→
132→        info!("Mock connection: {} <-> {}", self.name, other.name);
133→        Ok(())
134→    }
135→
136→    /// Initiate handshake with a permit
137→    pub fn handshake(&self, node_id: NodeId, permit: String) -> Result<()> {
138→        self.coordinator
139→            .cast(CoordinatorMessage::Connect { node_id, permit })
140→            .map_err(|e| anyhow::anyhow!("Failed to send Connect: {:?}", e))
141→    }
142→
143→    /// Wait for PeerAuthenticated event, returns (did, username)
144→    pub async fn wait_authenticated(&mut self, timeout: Duration) -> Result<(String, String)> {
145→        let deadline = tokio::time::Instant::now() + timeout;
146→        loop {
147→            match tokio::time::timeout_at(deadline, self.events.recv()).await {
148→                Ok(Some(CourierEvent::PeerAuthenticated { did, username, .. })) => {
149→                    info!("Peer '{}' authenticated with: {}", self.name, username);
150→                    return Ok((did, username));
151→                }
152→                Ok(Some(CourierEvent::ConnectionFailed { node_id, error })) => {
153→                    return Err(anyhow::anyhow!("Connection failed to {}: {}", node_id, error));
154→                }
155→                Ok(Some(_)) => continue,
156→                Ok(None) => return Err(anyhow::anyhow!("Event channel closed")),
157→                Err(_) => return Err(anyhow::anyhow!("Timeout waiting for authentication")),
158→            }
159→        }
160→    }
161→
162→    /// Wait for any CourierEvent
163→    pub async fn wait_event(&mut self, timeout: Duration) -> Result<CourierEvent> {
164→        tokio::time::timeout(timeout, self.events.recv())
165→            .await
166→            .map_err(|_| anyhow::anyhow!("Timeout waiting for event"))?
167→            .ok_or_else(|| anyhow::anyhow!("Event channel closed"))
168→    }
169→
170→    /// Shutdown the peer
171→    pub async fn shutdown(&self) {
172→        let _ = self.coordinator.cast(CoordinatorMessage::Shutdown);
173→    }
174→}
175→
176→impl Drop for Peer {
177→    fn drop(&mut self) {
178→        let _ = self.coordinator.cast(CoordinatorMessage::Shutdown);
179→    }
180→}
