244→    /// Import app from sample_apps directory, creating space + page
245→    ///
246→    /// Reads `permit_template.json` and `space_permit_template.json` from the app dir.
247→    pub async fn import_app(&self, space_name: &str, app_name: &str) -> Result<SpaceInfo> {
248→        let owner = self.owner();
249→        let user_info = owner.butler.user_info().await?;
250→
251→        // Read space template from the app's directory, falling back to our fixture
252→        let app_path = fixtures::app_dir(app_name);
253→        let space_template_path = app_path.join("space_permit_template.json");
254→        let space_template = if space_template_path.exists() {
255→            std::fs::read_to_string(&space_template_path)?
256→        } else {
257→            fixtures::space_template()
258→        };
259→
260→        // Create space
261→        let space = owner
262→            .butler
263→            .spaces()
264→            .create(space_name.to_string(), user_info.did.clone(), &space_template)
265→            .await?;
266→        info!("Space created: {}", space.id);
267→
268→        // Import page from app directory (reads permit_template.json automatically)
269→        // The app_path IS the page dir (contains permit_template.json + app subdirs with manifest.json)
270→        let page = owner.butler.apps().import_page(&space.id, &app_path).await?;
271→        info!("Page imported: {} from {:?}", page.id, app_path);
272→
273→        Ok(SpaceInfo {
274→            space_id: space.id,
275→            page_id: page.id,
276→        })
277→    }
