279→    /// Publish a space from owner to node
280→    pub async fn publish_space(&self, space_id: &str) -> Result<()> {
281→        let owner = self.owner();
282→        let node = self.node();
283→
284→        let (tx, rx) = tokio::sync::oneshot::channel();
285→        owner
286→            .coordinator
287→            .cast(CoordinatorMessage::GetPeerActor {
288→                node_id: node.node_id,
289→                response: tx,
290→            })
291→            .map_err(|e| anyhow::anyhow!("GetPeerActor failed: {:?}", e))?;
292→
293→        let peer_actor = rx
294→            .await
295→            .map_err(|_| anyhow::anyhow!("GetPeerActor channel closed"))?
296→            .ok_or_else(|| anyhow::anyhow!("No PeerActor for node"))?;
297→
298→        peer_actor
299→            .cast(PeerMessage::PublishSpace {
300→                space_id: space_id.to_string(),
301→            })
302→            .map_err(|e| anyhow::anyhow!("PublishSpace failed: {:?}", e))?;
303→
304→        info!("PublishSpace sent: {}", space_id);
305→        Ok(())
306→    }
