375→    /// Setup viewer (connect + handshake only, no space request)
376→    pub async fn setup_viewer(&mut self, index: usize, conn_string: &str) -> Result<()> {
377→        let node = self.node.as_ref().expect("Scenario has no node");
378→        let viewer = &self.viewers[index];
379→
380→        let conn = viewer
381→            .butler
382→            .nodes()
383→            .parse_connection_string(conn_string)
384→            .map_err(|e| anyhow::anyhow!("parse_connection_string failed: {}", e))?;
385→        let permit = conn.permit.clone();
386→
387→        viewer.connect_to(node)?;
388→        tokio::time::sleep(Duration::from_millis(10)).await;
389→        viewer.handshake(node.node_id, permit)?;
390→
391→        let viewer = self.viewer_mut(index);
392→        viewer.wait_authenticated(MOCK_TIMEOUT).await?;
393→
394→        Ok(())
395→    }
