397→    /// Wait for page to sync to a specific peer
398→    pub async fn wait_for_page(&self, peer: &Peer, page_id: &str) -> Result<()> {
399→        let butler = peer.butler.clone();
400→        let page_id = page_id.to_string();
401→        let deadline = tokio::time::Instant::now() + PAGE_SYNC_TIMEOUT;
402→
403→        loop {
404→            if butler.pages().get(&page_id).ok().flatten().is_some() {
405→                return Ok(());
406→            }
407→            if tokio::time::Instant::now() > deadline {
408→                return Err(anyhow::anyhow!(
409→                    "Timeout waiting for page {} on {}",
410→                    page_id,
411→                    peer.name
412→                ));
413→            }
414→            tokio::time::sleep(Duration::from_millis(50)).await;
415→        }
416→    }
417→
418→    /// Wait for page to sync to the node
419→    pub async fn wait_for_page_on_node(&self, page_id: &str) -> Result<()> {
420→        self.wait_for_page(self.node(), page_id).await
421→    }
422→
423→    /// Shutdown all peers
424→    pub async fn shutdown(&mut self) {
425→        if let Some(owner) = &self.owner {
426→            owner.shutdown().await;
427→        }
428→        if let Some(node) = &self.node {
429→            node.shutdown().await;
430→        }
431→        for viewer in &self.viewers {
432→            viewer.shutdown().await;
433→        }
434→    }
435→}
