 40→/// Read space template JSON from fixtures
 41→pub fn space_template() -> String {
 42→    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
 43→        .join("fixtures")
 44→        .join("space_template.json");
 45→    std::fs::read_to_string(&path)
 46→        .unwrap_or_else(|e| panic!("Failed to read space_template.json at {:?}: {}", path, e))
