    wait_for_layer_data(
        &s.node().butler,
        &page_id,
        &bare_layer_name,
        Duration::from_secs(10),
    )
    .await?;

    // Carol subscribes after layer creation.
    s.add_viewer(1, &viewer_link, &page_id).await?;

    let offline_viewer_data = wait_for_layer_data(
