    let mut found = false;
    while tokio::time::Instant::now() < deadline {
        if let Ok(sync_meta) = get_layer_json(s.node(), &page_id, &viewer_sync_meta_layer).await {
            if let Some(entry) = sync_meta.get(&bare_layer) {
