    let full_layer_name = create_rx
        .await
        .map_err(|_| anyhow::anyhow!("CreateDynamicLayer channel closed"))?
        .map_err(|e| anyhow::anyhow!("CreateDynamicLayer failed: {}", e))?;

    let bare_layer_name = full_layer_name
